INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 4.46, 'The Portland anti-ICE protester seen wearing an inflatable frog suit.', '这位波特兰反ICE抗议者被看到穿着一个充气青蛙服。', '/ðə pɔːɹtlənd æntaɪaɪsiːiː pɹətɛstɚ siːn wɛɹɪŋ ɐn ɪnfleɪɾəbəl fɹɑːɡ suːt./', '<span>The</span><span tid="91301">Portland</span><span tid="91302">anti-ICE</span><span tid="91303">protester</span><span tid="91304">seen</span><span tid="91305">wearing</span><span>an</span><span tid="91307" class="highlight highlight-a">inflatable</span><span pid="3483" class="highlight highlight-c">frog suit.</span>'
FROM episodes e WHERE e.video_id = '092INzNE5wBFz3c';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 4.46, 10.32, 'who has been popping up all over the internet, has claimed to be harmlessly protesting with humor.', '他已经在网络上频频出现，并声称自己只是用幽默方式进行无害抗议。', '/huː hæzbiːn pɑːpɪŋ ʌp ɔːl oʊvɚ ðɪ ɪntɚnɛt, hɐz kleɪmd təbi hɑːɹmləsli pɹətɛstɪŋ wɪð hjuːmɚ./', '<span>who</span><span>has</span><span>been</span><span pid="3484" class="highlight highlight-d">popping up</span><span pid="3485" class="highlight highlight-i">all over the internet,</span><span>has</span><span tid="91320" class="highlight highlight-a">claimed</span><span>to</span><span>be</span><span tid="91323" class="highlight highlight-a">harmlessly</span><span tid="91324" class="highlight highlight-a">protesting</span><span>with</span><span tid="91326" class="highlight highlight-a">humor.</span>'
FROM episodes e WHERE e.video_id = '092INzNE5wBFz3c';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 10.32, 17.78, 'But now a new report has revealed the protester under the costume to be a self-described proud Antifa terrorist.', '但现在有报道称，这名服装下的抗议者自称是一名自豪的Antifa恐怖分子。', '/bʌt naʊ ɐ nuː ɹᵻpɔːɹt hɐz ɹᵻviːld ðə pɹətɛstɚɹ ʌndɚ ðə kɔstuːm təbi ɐ sɛlfdᵻskɹaɪbd pɹaʊd æntɪfɑː tɛɹɚɹɪst./', '<span>But</span><span tid="91328">now</span><span>a</span><span tid="91330">new</span><span tid="91331">report</span><span>has</span><span tid="91333" class="highlight highlight-a">revealed</span><span>the</span><span tid="91335">protester</span><span tid="91336">under</span><span>the</span><span tid="91338" class="highlight highlight-a">costume</span><span>to</span><span>be</span><span>a</span><span tid="91342">self-described</span><span tid="91343">proud</span><span tid="91344">Antifa</span><span tid="91345" class="highlight highlight-a">terrorist.</span>'
FROM episodes e WHERE e.video_id = '092INzNE5wBFz3c';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 17.78, 19.66, 'Here''s everything you need to know.', '以下是你需要知道的全部情况。', '/hɪɹz ɛvɹɪθɪŋ juː niːd tə noʊ./', '<span>Here''s</span><span tid="91347">everything</span><span>you</span><span tid="91349">need</span><span>to</span><span>know.</span>'
