INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 19.66, 25.58, 'What became known online as the Portland frog has recently been spotted on a near daily basis.', '在网络上被称作“波特兰青蛙”的人物，最近几乎每天都被目击。', '/wʌt bɪkeɪm noʊn ɑːnlaɪn æz ðə pɔːɹtlənd fɹɑːɡ hɐz ɹiːsəntli bɪn spɑːɾᵻd ɔn ɐ nɪɹ deɪli beɪsɪs./', '<span>What</span><span tid="91353">became</span><span>known</span><span tid="91355">online</span><span>as</span><span>the</span><span tid="91358">Portland</span><span tid="91359">frog</span><span>has</span><span tid="91361">recently</span><span>been</span><span tid="91363" class="highlight highlight-a">spotted</span><span>on</span><span>a</span><span tid="91366">near</span><span pid="3486" class="highlight highlight-i">daily basis.</span>'
