INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 25.58, 31.76, 'sticking out like a sore thumb during clashes between federal agents and anti-ICE protesters.', '在联邦特工与反ICE抗议者的冲突中，他显得格外显眼。', '/stɪkɪŋ aʊt laɪk ɐ sɔːɹ θʌm dʊɹɹɪŋ klæʃᵻz bᵻtwiːn fɛdɚɹəl eɪdʒənts ænd æntaɪaɪsiːiː pɹətɛstɚz./', '<span pid="3487" class="highlight highlight-f">sticking out like a sore thumb</span><span tid="91375">during</span><span tid="91376" class="highlight highlight-a">clashes</span><span tid="91377">between</span><span pid="3488" class="highlight highlight-b">federal agents</span><span>and</span><span tid="91381">anti-ICE</span><span tid="91382">protesters.</span>'
