INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 31.76, 35.92, 'The goofy-looking frog has since been facing off with police.', '这只看起来滑稽的青蛙随后还与警方对峙。', '/ðə ɡuːfilʊkɪŋ fɹɑːɡ hɐz sɪns bɪn feɪsɪŋ ɔf wɪð pəliːs./', '<span>The</span><span tid="91384">goofy-looking</span><span tid="91385">frog</span><span>has</span><span tid="91387">since</span><span>been</span><span pid="3489" class="highlight highlight-d">facing off with</span><span tid="91392">police.</span>'
