INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 49.54, 55.44, 'It is a strategy to cut the narratives of the Trump administration, which says we are extremely violent.', '这是为了打破特朗普政府所宣称的“我们极端暴力”的叙事策略。', '/ɪɾ ɪz ɐ stɹæɾədʒi tə kʌt ðə næɹətɪvz ʌvðə tɹʌmp ɐdmɪnɪstɹeɪʃən, wɪtʃ sɛz wiː ɑːɹ ɛkstɹiːmli vaɪələnt./', '<span>It</span><span>is</span><span>a</span><span tid="91437" class="highlight highlight-a">strategy</span><span>to</span><span tid="91439" class="highlight highlight-a">cut</span><span>the</span><span tid="91441" class="highlight highlight-a">narratives</span><span>of</span><span>the</span><span tid="91444">Trump</span><span tid="91445">administration,</span><span>which</span><span tid="91447">says</span><span>we</span><span>are</span><span tid="91450" class="highlight highlight-a">extremely</span><span tid="91451" class="highlight highlight-a">violent.</span>'
FROM episodes e WHERE e.video_id = '092INzNE5wBFz3c';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 55.44, 62.14, 'No, we are protesting, but with humor, the Portland frog said, according to French outlet Le Monde.', '波特兰青蛙对法国媒体《世界报》表示：“不，我们是在抗议，但带着幽默。”', '/noʊ, wiː ɑːɹ pɹətɛstɪŋ, bʌt wɪð hjuːmɚ, ðə pɔːɹtlənd fɹɑːɡ sɛd, ɐkɔːɹdɪŋ tə fɹɛntʃ aʊtlɛt lə mɔnd./', '<span>No,</span><span>we</span><span>are</span><span tid="91455" class="highlight highlight-a">protesting,</span><span>but</span><span>with</span><span tid="91458" class="highlight highlight-a">humor,</span><span>the</span><span tid="91460">Portland</span><span tid="91461">frog</span><span tid="91462">said,</span><span tid="91463">according</span><span>to</span><span tid="91465">French</span><span tid="91466" class="highlight highlight-a">outlet</span><span tid="91467">Le</span><span tid="91468">Monde.</span>'
