INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 62.14, 65.76, 'It seems other protesters have followed the same sentiment.', '似乎其他抗议者也有同样的想法。', '/ɪt siːmz ʌðɚ pɹətɛstɚz hæv fɑːloʊd ðə seɪm sɛntɪmənt./', '<span>It</span><span tid="91470" class="highlight highlight-a">seems</span><span tid="91471">other</span><span tid="91472">protesters</span><span>have</span><span tid="91474">followed</span><span>the</span><span tid="91476">same</span><span tid="91477" class="highlight highlight-a">sentiment.</span>'
FROM episodes e WHERE e.video_id = '092INzNE5wBFz3c';
