INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 75.06, 79.54, 'Secretary, do you have a message to the protesters, especially the man in the chicken outfit?', '部长，您有话要对抗议者说吗，特别是那位穿鸡服的人？', '/sɛkɹətɹi, duː juː hæv ɐ mɛsɪdʒ tə ðə pɹətɛstɚz, ɪspɛʃəli ðə mæn ɪnðə tʃɪkɪn aʊtfɪt?/', '<span tid="91506" class="highlight highlight-a">Secretary,</span><span>do</span><span>you</span><span>have</span><span>a</span><span tid="91511" class="highlight highlight-a">message</span><span>to</span><span>the</span><span tid="91514">protesters,</span><span tid="91515" class="highlight highlight-a">especially</span><span>the</span><span tid="91517">man</span><span>in</span><span>the</span><span tid="91520">chicken</span><span tid="91521" class="highlight highlight-a">outfit?</span>'
