INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 85.8, 91.08, 'However, the identity of the mysterious inflatable amphibian has now been revealed.', '然而，这只神秘的充气两栖动物的身份现在已被揭露。', '/haʊɛvɚ, ðɪ aɪdɛntᵻɾi ʌvðə mɪstɪɹiəs ɪnfleɪɾəbəl æmfɪbiən hɐz naʊ bɪn ɹᵻviːld./', '<span tid="91540">However,</span><span>the</span><span tid="91542" class="highlight highlight-a">identity</span><span>of</span><span>the</span><span tid="91545">mysterious</span><span tid="91546" class="highlight highlight-a">inflatable</span><span tid="91547" class="highlight highlight-a">amphibian</span><span>has</span><span tid="91549">now</span><span>been</span><span tid="91551" class="highlight highlight-a">revealed.</span>'
