INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 151.8, 157.67, 'Todd has since walked back the comments by issuing an apology to the outlet, stating.', '托德随后通过向媒体道歉收回了这些言论，他表示：', '/tɑːd hɐz sɪns wɔːkt bæk ðə kɑːmɛnts baɪ ɪʃuːɪŋ ɐn ɐpɑːlədʒi tə ðɪ aʊtlɛt, steɪɾɪŋ./', '<span tid="91708">Todd</span><span>has</span><span tid="91710">since</span><span tid="91711">walked</span><span tid="91712" class="highlight highlight-a">back</span><span>the</span><span tid="91714" class="highlight highlight-a">comments</span><span>by</span><span tid="91716" class="highlight highlight-a">issuing</span><span>an</span><span tid="91718" class="highlight highlight-a">apology</span><span>to</span><span>the</span><span tid="91721" class="highlight highlight-a">outlet,</span><span tid="91722">stating.</span>'
