INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 2.12, 5.74, 'British English, American English, Canadian English, Australian English.', '英式英语、美式英语、加式英语、澳式英语。', '/bɹɪɾɪʃ ɪŋɡlɪʃ, ɐmɛɹɪkən ɪŋɡlɪʃ, kɐneɪdiən ɪŋɡlɪʃ, ɔːstɹeɪliən ɪŋɡlɪʃ./', '<span tid="89802">British</span><span tid="89803">English,</span><span tid="89804">American</span><span tid="89805">English,</span><span tid="89806">Canadian</span><span tid="89807">English,</span><span tid="89808">Australian</span><span tid="89809">English.</span>'
