INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 11.28, 16.98, 'You see, when you first start learning a language, this is a question that will inevitably come up.', '你看，当你刚开始学习一门语言时，这个问题几乎是必然会出现的。', '/juː siː, wɛn juː fɜːst stɑːɹt lɜːnɪŋ ɐ læŋɡwɪdʒ, ðɪs ɪz ɐ kwɛstʃən ðæt wɪl ɪnɛvᵻɾəbli kʌm ʌp./', '<span>You</span><span tid="89829">see,</span><span>when</span><span>you</span><span tid="89832">first</span><span tid="89833">start</span><span tid="89834">learning</span><span>a</span><span tid="89836">language,</span><span>this</span><span>is</span><span>a</span><span tid="89840">question</span><span>that</span><span>will</span><span tid="89843" class="highlight highlight-a">inevitably</span><span pid="787" class="highlight highlight-d">come up.</span>'
