INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 27, 98.14, 101.86, 'For the most part, a British speaker can understand an American speaker.', '大多数情况下，英国人能听懂美国人。', '/fɚðə moʊst pɑːɹt, ɐ bɹɪɾɪʃ spiːkɚ kæn ʌndɚstænd ɐn ɐmɛɹɪkən spiːkɚ./', '<span>For</span><span>the</span><span tid="90073">most</span><span tid="90074">part,</span><span>a</span><span tid="90076">British</span><span tid="90077">speaker</span><span>can</span><span tid="90079">understand</span><span>an</span><span tid="90081">American</span><span tid="90082">speaker.</span>'
