INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 28, 101.86, 105.84, 'an American speaker can understand an Australian, and so on and so on.', '美国人也能听懂澳大利亚人，依此类推。', '/ɐn ɐmɛɹɪkən spiːkɚ kæn ʌndɚstænd ɐn ɔːstɹeɪliən, ænd soʊ ɔn ænd soʊ ɔn./', '<span>an</span><span tid="90084">American</span><span tid="90085">speaker</span><span>can</span><span tid="90087">understand</span><span>an</span><span tid="90089">Australian,</span><span pid="785" class="highlight highlight-i">and so on</span><span pid="785" class="highlight highlight-i">and so on.</span>'
