INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 31, 110.66, 115.62, 'If you focus on learning standard English, you will be understood in most of the world.', '如果你专注学习标准英语，你在世界上大多数地方都能被理解。', '/ɪf juː foʊkəs ɔn lɜːnɪŋ stændɚd ɪŋɡlɪʃ, juː wɪl biː ʌndɚstʊd ɪn moʊst əv ðə wɜːld./', '<span>If</span><span>you</span><span tid="90112">focus</span><span>on</span><span tid="90114">learning</span><span tid="90115" class="highlight highlight-a">standard</span><span tid="90116">English,</span><span>you</span><span>will</span><span>be</span><span tid="90120">understood</span><span>in</span><span tid="90122">most</span><span>of</span><span>the</span><span tid="90125">world.</span>'
FROM episodes e WHERE e.video_id = '094XeDfApqGbHiX';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
