INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 76, 308.78, 314.52, 'So with that said, let me know in the comments, which variety of English are you learning?', '所以说完这些，请在评论区告诉我——你现在学的是哪种英语？', '/soʊ wɪð ðæt sɛd, lɛt miː noʊ ɪnðə kɑːmɛnts, wɪtʃ vɚɹaɪəɾi ʌv ɪŋɡlɪʃ ɑːɹ juː lɜːnɪŋ?/', '<span>So</span><span pid="792" class="highlight highlight-i">with that said,</span><span>let</span><span>me</span><span>know</span><span>in</span><span>the</span><span tid="90739" class="highlight highlight-a">comments,</span><span>which</span><span tid="90741" class="highlight highlight-a">variety</span><span>of</span><span tid="90743">English</span><span>are</span><span>you</span><span tid="90746">learning?</span>'
