INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 26.18, 29.02, 'No one to reminisce with down the road?', '没有人在日后一起回忆？', '/noʊwʌn tə ɹɛmᵻnɪs wɪð daʊn ðə ɹoʊd?/', '<span>No</span><span>one</span><span>to</span><span tid="88950" class="highlight highlight-a">reminisce</span><span>with</span><span tid="88952">down</span><span>the</span><span tid="88954">road?</span>'
