INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 35.02, 38.66, 'Patagonia was the kind of place I''ve dreamed about for years.', '巴塔哥尼亚是我梦了好多年的地方。', '/pætæɡəniə wʌzðə kaɪnd ʌv pleɪs aɪv dɹiːmd ɐbaʊt fɔːɹ jɪɹz./', '<span tid="88962">Patagonia</span><span>was</span><span>the</span><span tid="88965">kind</span><span>of</span><span tid="88967">place</span><span>I''ve</span><span tid="88969">dreamed</span><span>about</span><span>for</span><span tid="88972">years.</span>'
