INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 39.06, 42.78, 'Jagged mountains, endless sky, wild weather.', '参差的山峰、无尽的天空、变幻莫测的天气。', '/dʒæɡᵻd maʊntɪnz, ɛndləs skaɪ, waɪld wɛðɚ./', '<span tid="88973" class="highlight highlight-a">Jagged</span><span tid="88974">mountains,</span><span tid="88975">endless</span><span tid="88976">sky,</span><span tid="88977" class="highlight highlight-a">wild</span><span tid="88978">weather.</span>'
