INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 109.44, 112.82, 'Realizing that if I keep waiting for everything to align.', '意识到如果我总是等一切完美契合。', '/ɹiːəlaɪzɪŋ ðæt ɪf aɪ kiːp weɪɾɪŋ fɔːɹ ɛvɹɪθɪŋ tʊ ɐlaɪn./', '<span tid="89116" class="highlight highlight-a">Realizing</span><span>that</span><span>if</span><span>I</span><span tid="89120">keep</span><span tid="89121">waiting</span><span>for</span><span tid="89123">everything</span><span>to</span><span tid="89125" class="highlight highlight-a">align.</span>'
