INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 113.26, 116.72, 'I might miss the moments I''ve spent years dreaming about.', '我可能会错过那些梦了多年的时刻。', '/aɪ maɪt mɪs ðə moʊmənts aɪv spɛnt jɪɹz dɹiːmɪŋ ɐbaʊt./', '<span>I</span><span tid="89127" class="highlight highlight-a">might</span><span tid="89128">miss</span><span>the</span><span tid="89130" class="highlight highlight-a">moments</span><span>I''ve</span><span tid="89132">spent</span><span tid="89133">years</span><span tid="89134">dreaming</span><span>about.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 121.74, 125.32, 'Later that afternoon, I hiked up to Mirador Condor.', '那天下午，我徒步登上了秃鹰观景台。', '/leɪɾɚ ðæt æftɚnuːn, aɪ haɪkt ʌp tə mɜːɹɐdɔːɹ kɑːndɔːɹ./', '<span tid="89136" class="highlight highlight-a">Later</span><span>that</span><span tid="89138">afternoon,</span><span>I</span><span tid="89140" class="highlight highlight-a">hiked</span><span>up</span><span>to</span><span tid="89143">Mirador</span><span tid="89144">Condor.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 125.58, 129.96, 'a rocky outcrop overlooking the turquoise waters of Lago Pejo.', '那是一处俯瞰碧蓝湖泊的岩石高地。', '/ɐ ɹɑːki aʊtkɹɑːp oʊvɚlʊkɪŋ ðə tɜːkwɔɪs wɔːɾɚz ʌv leɪɡoʊ piːdʒoʊ./', '<span>a</span><span tid="89146" class="highlight highlight-a">rocky</span><span tid="89147" class="highlight highlight-a">outcrop</span><span tid="89148" class="highlight highlight-a">overlooking</span><span>the</span><span tid="89150" class="highlight highlight-a">turquoise</span><span tid="89151">waters</span><span>of</span><span tid="89153">Lago</span><span tid="89154">Pejo.</span>'
