INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 33, 217.64, 219.76, 'you just kind of have to go for it.', '你只能随时出发，别犹豫。', '/juː dʒʌst kaɪnd ʌv hæv tə ɡoʊ fɔːɹ ɪt./', '<span>you</span><span>just</span><span tid="89306">kind</span><span>of</span><span>have</span><span>to</span><span pid="3282" class="highlight highlight-i">go for it.</span>'
