INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 225.12, 230.36, 'then opened up to a spectacular view of the Rio de los Vuelta''s valley below.', '然后豁然开朗，可以俯瞰下方令人惊叹的回转河谷。', '/ðɛn oʊpənd ʌp tʊ ɐ spɛktækjʊlɚ vjuː ʌvðə ɹiːoʊ də lɑːs vjuːəltəz væli bᵻloʊ./', '<span>then</span><span tid="89325">opened</span><span>up</span><span>to</span><span>a</span><span tid="89329" class="highlight highlight-a">spectacular</span><span tid="89330" class="highlight highlight-a">view</span><span>of</span><span>the</span><span tid="89333">Rio</span><span tid="89334">de</span><span tid="89335">los</span><span tid="89336">Vuelta''s</span><span tid="89337" class="highlight highlight-a">valley</span><span tid="89338">below.</span>'
