INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 232.12, 236.06, 'And somewhere along that trail, I finally started to feel it.', '就在那条路上某个时刻，我终于开始有了那种感觉。', '/ænd sʌmwɛɹ ɐlɔŋ ðæt tɹeɪl, aɪ faɪnəli stɑːɹɾᵻd tə fiːl ɪt./', '<span>And</span><span tid="89340" class="highlight highlight-a">somewhere</span><span tid="89341">along</span><span>that</span><span tid="89343" class="highlight highlight-a">trail,</span><span>I</span><span tid="89345">finally</span><span tid="89346">started</span><span>to</span><span tid="89348">feel</span><span>it.</span>'
