INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 44, 275.1, 280.8, 'The kind of thing that reminds you why you came all this way in the first place.', '也正是这种时刻，会让你想起自己为何要千里迢迢来到这里。', '/ðə kaɪnd ʌv θɪŋ ðæt ɹᵻmaɪndz juː waɪ juː keɪm ɔːl ðɪs weɪ ɪnðə fɜːst pleɪs./', '<span>The</span><span tid="89450">kind</span><span>of</span><span>thing</span><span>that</span><span tid="89454" class="highlight highlight-a">reminds</span><span>you</span><span>why</span><span>you</span><span tid="89458">came</span><span>all</span><span>this</span><span tid="89461" class="highlight highlight-a">way</span><span pid="3285" class="highlight highlight-i">in the first place.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 45, 292.6, 295.62, 'Sunrise on Fitzroy is truly something else.', '菲茨罗伊峰的日出真是无法形容的震撼。', '/sʌnɹaɪz ɔn fɪtsɹɔɪ ɪz tɹuːli sʌmθɪŋ ɛls./', '<span tid="89466" class="highlight highlight-a">Sunrise</span><span>on</span><span tid="89468">Fitzroy</span><span>is</span><span tid="89470" class="highlight highlight-a">truly</span><span pid="3286" class="highlight highlight-i">something else.</span>'
