INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 46, 295.82, 302.62, 'The mountains here feel almost alive, like a giant canvas catching the first brushstrokes of light.', '这些山峰仿佛有生命一般，像巨大的画布，捕捉到第一缕阳光的笔触。', '/ðə maʊntɪnz hɪɹ fiːl ɔːlmoʊst ɐlaɪv, laɪk ɐ dʒaɪənt kænvəs kætʃɪŋ ðə fɜːst bɹʌʃ stɹoʊks ʌv laɪt./', '<span>The</span><span tid="89474">mountains</span><span>here</span><span tid="89476">feel</span><span tid="89477">almost</span><span tid="89478">alive,</span><span>like</span><span>a</span><span tid="89481">giant</span><span tid="89482" class="highlight highlight-a">canvas</span><span tid="89483">catching</span><span>the</span><span tid="89485">first</span><span tid="89486" class="highlight highlight-a">brushstrokes</span><span>of</span><span tid="89488" class="highlight highlight-a">light.</span>'
