INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 47, 303.5, 306.7, 'For a few brief moments, everything glows.', '短短几分钟，一切都在发光。', '/fɚɹə fjuː bɹiːf moʊmənts, ɛvɹɪθɪŋ ɡloʊz./', '<span>For</span><span>a</span><span tid="89491">few</span><span tid="89492">brief</span><span tid="89493" class="highlight highlight-a">moments,</span><span tid="89494">everything</span><span tid="89495" class="highlight highlight-a">glows.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 48, 307.36, 313.82, 'The peaks shift from a deep blue to fire orange, then fade into soft pinks and golds.', '山峰的颜色从深蓝转为火橙，又慢慢融入柔和的粉金。', '/ðə piːks ʃɪft fɹʌm ɐ diːp bluː tə faɪɚɹ ɔɹɪndʒ, ðɛn feɪd ɪntʊ sɔft pɪŋks ænd ɡoʊldz./', '<span>The</span><span tid="89497" class="highlight highlight-a">peaks</span><span tid="89498" class="highlight highlight-a">shift</span><span>from</span><span>a</span><span tid="89501">deep</span><span tid="89502">blue</span><span>to</span><span tid="89504" class="highlight highlight-a">fire</span><span tid="89505">orange,</span><span>then</span><span pid="3279" class="highlight highlight-d">fade into</span><span tid="89509">soft</span><span tid="89510">pinks</span><span>and</span><span tid="89512">golds.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 49, 314.18, 318.0, 'There''s nothing to do in a moment like that, except be still.', '那一刻，你什么也不需要做，只要静静待着。', '/ðɛɹz nʌθɪŋ tə duː ɪn ɐ moʊmənt laɪk ðæt, ɛksɛpt biː stɪl./', '<span>There''s</span><span tid="89514">nothing</span><span>to</span><span>do</span><span>in</span><span>a</span><span tid="89519" class="highlight highlight-a">moment</span><span>like</span><span>that,</span><span tid="89522" class="highlight highlight-a">except</span><span>be</span><span tid="89524">still.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 50, 318.28, 319.88, 'Just take it all in.', '让自己完全沉浸其中。', '/dʒʌst teɪk ɪɾ ɔːl ɪn./', '<span>Just</span><span tid="89526">take</span><span>it</span><span>all</span><span>in.</span>'
