INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 51, 341.36, 346.74, 'On my final day in Patagonia, fresh snow dusted the higher peaks.', '在巴塔哥尼亚的最后一天，雪花轻覆在高处的山峰上。', '/ɔn maɪ faɪnəl deɪ ɪn pætæɡəniə, fɹɛʃ snoʊ dʌstᵻd ðə haɪɚ piːks./', '<span>On</span><span>my</span><span tid="89532">final</span><span>day</span><span>in</span><span tid="89535">Patagonia,</span><span tid="89536" class="highlight highlight-a">fresh</span><span tid="89537">snow</span><span tid="89538" class="highlight highlight-a">dusted</span><span>the</span><span tid="89540">higher</span><span tid="89541" class="highlight highlight-a">peaks.</span>'
