INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 52, 347.04, 352.06, 'only to be immediately swept away by the fierce winds blowing off the ice field.', '但立刻就被冰原上吹来的狂风一扫而空。', '/oʊnli təbi ɪmiːdɪətli swɛpt ɐweɪ baɪ ðə fɪɹs wɪndz bloʊɪŋ ɔf ðɪ aɪs fiːld./', '<span tid="89542">only</span><span>to</span><span>be</span><span tid="89545" class="highlight highlight-a">immediately</span><span tid="89546" class="highlight highlight-a">swept</span><span tid="89547">away</span><span>by</span><span>the</span><span tid="89550" class="highlight highlight-a">fierce</span><span tid="89551">winds</span><span tid="89552">blowing</span><span tid="89553">off</span><span>the</span><span tid="89555">ice</span><span tid="89556" class="highlight highlight-a">field.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 53, 354.3, 360.2, 'I wandered out into the wide open plains outside of town, hoping to spot some guanaco.', '我走到镇外辽阔的平原，希望能看到几只原驼。', '/aɪ wɔndɚd aʊt ɪntʊ ðə waɪd oʊpən pleɪnz aʊtsaɪd ʌv taʊn, hoʊpɪŋ tə spɑːt sʌm ɡwɑːnɑːkoʊ./', '<span>I</span><span tid="89558" class="highlight highlight-a">wandered</span><span tid="89559">out</span><span tid="89560" class="highlight highlight-a">into</span><span>the</span><span pid="3287" class="highlight highlight-c">wide open</span><span tid="89564" class="highlight highlight-a">plains</span><span tid="89565">outside</span><span>of</span><span tid="89567">town,</span><span tid="89568">hoping</span><span>to</span><span tid="89570" class="highlight highlight-a">spot</span><span>some</span><span tid="89572" class="highlight highlight-a">guanaco.</span>'
FROM episodes e WHERE e.video_id = '095LH2nk7s7LHpu';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 54, 360.72, 362.48, 'And man was I in luck.', '真是走运，我遇到了。', '/ænd mæn wʌz aɪ ɪn lʌk./', '<span>And</span><span tid="89574">man</span><span>was</span><span>I</span><span>in</span><span tid="89578">luck.</span>'
