INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 53, 313.28, 318.2, 'Hi guys, I''m on my way to campus and the weather is quite chilly today.', '嗨大家，我现在在去学校的路上，今天的天气挺冷的。', '/haɪ ɡaɪz, aɪm ɔn maɪ weɪ tə kæmpəs ænd ðə wɛðɚɹ ɪz kwaɪt tʃɪli tədeɪ./', '<span>Hi</span><span tid="88010">guys,</span><span>I''m</span><span>on</span><span>my</span><span tid="88014" class="highlight highlight-a">way</span><span>to</span><span tid="88016">campus</span><span>and</span><span>the</span><span tid="88019">weather</span><span>is</span><span tid="88021">quite</span><span tid="88022" class="highlight highlight-a">chilly</span><span tid="88023">today.</span>'
FROM episodes e WHERE e.video_id = '096DK69nK0coOG5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 54, 318.2, 322.18, 'It''s actually feeling like fall and I feel like today was a pretty meeting heavy day.', '真有点秋天的感觉，今天一整天基本都在开会。', '/ɪts æktʃuːəli fiːlɪŋ laɪk fɔːl ænd aɪ fiːl laɪk tədeɪ wʌzɐ pɹɪɾi miːɾɪŋ hɛvi deɪ./', '<span>It''s</span><span tid="88025">actually</span><span tid="88026">feeling</span><span>like</span><span tid="88028">fall</span><span>and</span><span>I</span><span tid="88031">feel</span><span>like</span><span tid="88033">today</span><span>was</span><span>a</span><span tid="88036" class="highlight highlight-a">pretty</span><span tid="88037" class="highlight highlight-a">meeting</span><span tid="88038" class="highlight highlight-a">heavy</span><span>day.</span>'
