INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 61, 383.06, 387.08, 'But it''s been really helpful to just have a visual tool that we can play with.', '这个可视化工具真的很有帮助，', '/bʌt ɪts bɪn ɹiəli hɛlpfəl tə dʒʌst hæv ɐ vɪʒuːəl tuːl ðæt wiː kæn pleɪ wɪð./', '<span>But</span><span>it''s</span><span>been</span><span tid="88160">really</span><span tid="88161" class="highlight highlight-a">helpful</span><span>to</span><span>just</span><span>have</span><span>a</span><span tid="88166">visual</span><span tid="88167">tool</span><span>that</span><span>we</span><span>can</span><span tid="88171">play</span><span>with.</span>'
