INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 62, 387.08, 391.1, 'and lay out the different parts of the model so we can learn how it works.', '我们可以直观地搭建模型的各个部分，理解它的运行原理。', '/ænd leɪ aʊt ðə dɪfɹənt pɑːɹts ʌvðə mɑːdəl soʊ wiː kæn lɜːn haʊ ɪt wɜːks./', '<span>and</span><span tid="88174">lay</span><span tid="88175">out</span><span>the</span><span tid="88177">different</span><span tid="88178">parts</span><span>of</span><span>the</span><span tid="88181" class="highlight highlight-a">model</span><span>so</span><span>we</span><span>can</span><span tid="88185">learn</span><span>how</span><span>it</span><span tid="88188">works.</span>'
