INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 63, 393.88, 403.96, 'Hello, guys, I am back home from class and it is 9 50 p .m., but I''m actually going to go work out really quickly.', '大家好，我刚下课回到家，现在是晚上9点50分，但我打算赶紧去锻炼一下。', '/həloʊ, ɡaɪz, aɪɐm bæk hoʊm fɹʌm klæs ænd ɪɾ ɪz naɪn fɪfti piː .ɛm., bʌt aɪm æktʃuːəli ɡoʊɪŋ tə ɡoʊ wɜːk aʊt ɹiəli kwɪkli./', '<span>Hello,</span><span tid="88190">guys,</span><span>I</span><span>am</span><span tid="88193" class="highlight highlight-a">back</span><span tid="88194">home</span><span>from</span><span tid="88196">class</span><span>and</span><span>it</span><span>is</span><span>9</span><span>50</span><span>p</span><span>.m.,</span><span>but</span><span>I''m</span><span tid="88206">actually</span><span>going</span><span>to</span><span>go</span><span tid="88210">work</span><span tid="88211">out</span><span tid="88212">really</span><span tid="88213">quickly.</span>'
