INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 68, 425.74, 429.54, 'and then come back and shower But yeah, let''s go.', '然后回来洗澡。好啦，出发。', '/ænd ðɛn kʌm bæk ænd ʃaʊɚ bʌt jɛh, lɛts ɡoʊ./', '<span>and</span><span>then</span><span tid="88295">come</span><span tid="88296" class="highlight highlight-a">back</span><span>and</span><span tid="88298" class="highlight highlight-a">shower</span><span>But</span><span>yeah,</span><span>let''s</span><span>go.</span>'
