INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 69, 444.4, 448.8, 'All right, guys, I just washed up and I''m getting ready for bread, breadbed.', '好啦大家，我刚洗完澡，准备去睡觉——差点说成‘面包’。', '/ɔːl ɹaɪt, ɡaɪz, aɪ dʒʌst wɑːʃt ʌp ænd aɪm ɡɛɾɪŋ ɹɛdi fɔːɹ bɹɛd, bɹɛdbɛd./', '<span>All</span><span tid="88304" class="highlight highlight-a">right,</span><span tid="88305">guys,</span><span>I</span><span>just</span><span pid="1939" class="highlight highlight-d">washed up</span><span>and</span><span>I''m</span><span>getting</span><span tid="88313">ready</span><span>for</span><span tid="88315">bread,</span><span tid="88316">breadbed.</span>'
