INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 76, 471.62, 478.74, 'And honestly, the first time in a while of me just having the space to breathe and having silence.', '老实说，那是我好久以来第一次能真正喘口气、享受安静的时光。', '/ænd ɑːnɪstli, ðə fɜːst taɪm ɪn ɐ waɪl ʌv miː dʒʌst hævɪŋ ðə speɪs tə bɹiːð ænd hævɪŋ saɪləns./', '<span>And</span><span tid="88383" class="highlight highlight-a">honestly,</span><span>the</span><span tid="88385">first</span><span tid="88386">time</span><span>in</span><span>a</span><span tid="88389">while</span><span>of</span><span>me</span><span>just</span><span>having</span><span>the</span><span tid="88395">space</span><span>to</span><span tid="88397">breathe</span><span>and</span><span>having</span><span tid="88400" class="highlight highlight-a">silence.</span>'
