INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 77, 478.74, 483.14, 'And I think it just reminded me of how important rest is.', '这也让我重新意识到休息有多重要。', '/ænd aɪ θɪŋk ɪt dʒʌst ɹᵻmaɪndᵻd miː ʌv haʊ ɪmpɔːɹtənt ɹɛst ɪz./', '<span>And</span><span>I</span><span>think</span><span>it</span><span>just</span><span tid="88406" class="highlight highlight-a">reminded</span><span>me</span><span>of</span><span>how</span><span tid="88410">important</span><span tid="88411">rest</span><span>is.</span>'
