INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 78, 483.14, 484.7, 'And I''m going to be honest with you guys.', '说实话，', '/ænd aɪm ɡoʊɪŋ təbi ɑːnɪst wɪð juː ɡaɪz./', '<span>And</span><span>I''m</span><span>going</span><span>to</span><span>be</span><span tid="88418">honest</span><span>with</span><span>you</span><span tid="88421">guys.</span>'
