INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 79, 484.7, 491.32, 'I feel like I haven''t given myself true rest the past month or month and a half, I would say.', '过去一个多月我都没给自己真正的休息。', '/aɪ fiːl laɪk aɪ hævənt ɡɪvən maɪsɛlf tɹuː ɹɛst ðə pæst mʌnθ ɔːɹ mʌnθ ænd ɐ hæf, aɪ wʊd seɪ./', '<span>I</span><span tid="88423">feel</span><span>like</span><span>I</span><span>haven''t</span><span tid="88427">given</span><span tid="88428">myself</span><span tid="88429">true</span><span tid="88430">rest</span><span>the</span><span tid="88432">past</span><span tid="88433">month</span><span>or</span><span tid="88435">month</span><span>and</span><span>a</span><span tid="88438">half,</span><span>I</span><span>would</span><span tid="88441">say.</span>'
