INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 80, 491.32, 494.58, 'There were just a lot of different things going on that I was doing.', '因为我在忙着做各种不同的事情。', '/ðɛɹwɜː dʒʌst ɐ lɑːt ʌv dɪfɹənt θɪŋz ɡoʊɪŋ ɔn ðæt aɪ wʌz duːɪŋ./', '<span>There</span><span>were</span><span>just</span><span>a</span><span tid="88446">lot</span><span>of</span><span tid="88448">different</span><span>things</span><span>going</span><span>on</span><span>that</span><span>I</span><span>was</span><span>doing.</span>'
