INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 82, 500.12, 503.74, 'And it''s crazy what just a little bit of rest could do.', '但真的，短短一点点休息就能带来巨大的变化。', '/ænd ɪts kɹeɪzi wʌt dʒʌst ɐ lɪɾəl bɪt ʌv ɹɛst kʊd duː./', '<span>And</span><span>it''s</span><span tid="88481">crazy</span><span>what</span><span>just</span><span>a</span><span tid="88485">little</span><span tid="88486">bit</span><span>of</span><span tid="88488">rest</span><span>could</span><span>do.</span>'
