INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 83, 503.74, 510.32, 'because after I came back from home, I just felt so refreshed and excited to get back into school.', '从家回来后，我整个人都焕然一新，又重新有动力回到学习中。', '/bɪkʌz æftɚɹ aɪ keɪm bæk fɹʌm hoʊm, aɪ dʒʌst fɛlt soʊ ɹᵻfɹɛʃt ænd ɛksaɪɾᵻd tə ɡɛt bæk ɪntʊ skuːl./', '<span>because</span><span tid="88492">after</span><span>I</span><span tid="88494">came</span><span tid="88495" class="highlight highlight-a">back</span><span>from</span><span tid="88497">home,</span><span>I</span><span>just</span><span tid="88500">felt</span><span>so</span><span tid="88502" class="highlight highlight-a">refreshed</span><span>and</span><span tid="88504">excited</span><span>to</span><span>get</span><span tid="88507" class="highlight highlight-a">back</span><span tid="88508" class="highlight highlight-a">into</span><span tid="88509" class="highlight highlight-a">school.</span>'
