INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 84, 510.32, 513.38, 'Even today during class, I was sitting there.', '就像今天上课的时候，', '/iːvən tədeɪ dʊɹɹɪŋ klæs, aɪ wʌz sɪɾɪŋ ðɛɹ./', '<span tid="88510">Even</span><span tid="88511">today</span><span tid="88512">during</span><span tid="88513">class,</span><span>I</span><span>was</span><span tid="88516">sitting</span><span>there.</span>'
