INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 85, 513.38, 518.44, 'My brain was being stretched by very technical language that I honestly didn''t understand.', '虽然我脑子被那些我完全听不懂的技术词汇拉扯着，', '/maɪ bɹeɪn wʌz biːɪŋ stɹɛtʃt baɪ vɛɹi tɛknɪkəl læŋɡwɪdʒ ðæt aɪ ɑːnɪstli dɪdnt ʌndɚstænd./', '<span>My</span><span tid="88519">brain</span><span>was</span><span>being</span><span tid="88522" class="highlight highlight-a">stretched</span><span>by</span><span>very</span><span tid="88525" class="highlight highlight-a">technical</span><span tid="88526">language</span><span>that</span><span>I</span><span tid="88529" class="highlight highlight-a">honestly</span><span>didn''t</span><span tid="88531">understand.</span>'
