INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 90, 538.78, 543.02, 'And then the second part that I want to talk about is the importance of silence.', '我还想聊聊第二个话题——‘安静’的重要性。', '/ænd ðɛn ðə sɛkənd pɑːɹt ðæt aɪ wɔnt tə tɔːk ɐbaʊt ɪz ðɪ ɪmpɔːɹtəns ʌv saɪləns./', '<span>And</span><span>then</span><span>the</span><span tid="88605">second</span><span tid="88606">part</span><span>that</span><span>I</span><span>want</span><span>to</span><span tid="88611">talk</span><span>about</span><span>is</span><span>the</span><span tid="88615">importance</span><span>of</span><span tid="88617" class="highlight highlight-a">silence.</span>'
