INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 95, 561.34, 564.8, 'and to just kind of sit there with your thoughts.', '去坐下来，好好和自己的思绪待在一起。', '/ænd tə dʒʌst kaɪnd ʌv sɪt ðɛɹ wɪð jʊɹ θɔːts./', '<span>and</span><span>to</span><span>just</span><span tid="88680">kind</span><span>of</span><span tid="88682">sit</span><span>there</span><span>with</span><span>your</span><span tid="88686">thoughts.</span>'
FROM episodes e WHERE e.video_id = '096DK69nK0coOG5';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 96, 564.8, 568.86, 'And so for me, when I went back home and just found moments of silence.', '我这次回家时，正是在那种安静中，', '/ænd soʊ fɔːɹ miː, wɛn aɪ wɛnt bæk hoʊm ænd dʒʌst faʊnd moʊmənts ʌv saɪləns./', '<span>And</span><span>so</span><span>for</span><span>me,</span><span>when</span><span>I</span><span>went</span><span tid="88694" class="highlight highlight-a">back</span><span tid="88695">home</span><span>and</span><span>just</span><span tid="88698">found</span><span tid="88699" class="highlight highlight-a">moments</span><span>of</span><span tid="88701" class="highlight highlight-a">silence.</span>'
