INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 101, 589.64, 595.12, 'And that''s honestly how I am sustained through doing work and school and everything else.', '说实话，这就是我能同时撑住工作、上学和生活的原因。', '/ænd ðæts ɑːnɪstli haʊ aɪɐm səsteɪnd θɹuː duːɪŋ wɜːk ænd skuːl ænd ɛvɹɪθɪŋ ɛls./', '<span>And</span><span>that''s</span><span tid="88772" class="highlight highlight-a">honestly</span><span>how</span><span>I</span><span>am</span><span tid="88776" class="highlight highlight-a">sustained</span><span tid="88777">through</span><span>doing</span><span tid="88779">work</span><span>and</span><span tid="88781" class="highlight highlight-a">school</span><span>and</span><span tid="88783">everything</span><span tid="88784">else.</span>'
