FROM episodes e WHERE e.video_id = '098N6pUDPZmTL2j';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 173, 695.24, 696.34, 'And they finally have.', '现在它们终于开始用了。', '/ænd ðeɪ faɪnəli hæv./', '<span>And</span><span>they</span><span tid="84432">finally</span><span>have.</span>'
