INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 174, 696.34, 698.52, 'So I''m very happy about that.', '我真的太开心了。', '/soʊ aɪm vɛɹi hæpi ɐbaʊt ðæt./', '<span>So</span><span>I''m</span><span>very</span><span tid="84437">happy</span><span>about</span><span>that.</span>'
