INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 192, 776.68, 779.94, 'But it''s honestly the highlight of my day, like coming home and seeing them.', '每天回家看到它们，真的是我一天中最开心的时刻。', '/bʌt ɪts ɑːnɪstli ðə haɪlaɪt ʌv maɪ deɪ, laɪk kʌmɪŋ hoʊm ænd siːɪŋ ðɛm./', '<span>But</span><span>it''s</span><span tid="84673" class="highlight highlight-a">honestly</span><span>the</span><span tid="84675" class="highlight highlight-a">highlight</span><span>of</span><span>my</span><span>day,</span><span>like</span><span tid="84680">coming</span><span tid="84681">home</span><span>and</span><span tid="84683">seeing</span><span>them.</span>'
