INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 123, 490.28, 492.92, 'But this was something that just felt very monumental and special.', '但这件事感觉非常重要且特别。', 'bʌt ðɪs wʌz sʌmθɪŋ ðæt dʒʌst fɛlt vɛɹi mɑːnjuːmɛntəl ænd spɛʃəl.', '<span>But</span><span>this</span><span>was</span><span>something</span><span>that</span><span>just</span><span tid="81641">felt</span><span>very</span><span tid="81643" class="highlight highlight-a">monumental</span><span>and</span><span tid="81645">special.</span>'
