INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 124, 492.92, 496.04, 'And so I''m glad that I have been talking to my close friends about it.', '所以我很高兴我一直在和亲密的朋友聊这件事。', 'ænd soʊ aɪm ɡlæd ðæt aɪ hɐvbɪn tɔːkɪŋ tə maɪ kloʊs fɹɛndz ɐbaʊt ɪt.', '<span>And</span><span>so</span><span>I''m</span><span tid="81649">glad</span><span>that</span><span>I</span><span>have</span><span>been</span><span tid="81654">talking</span><span>to</span><span>my</span><span pid="539" class="highlight highlight-c">close friends</span><span>about</span><span>it.</span>'
