INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 153, 587.72, 589.4, 'It''s a memoir It''s Patti Smith''s memoir.', '这是回忆录，是Patti Smith的回忆录。', 'ɪts ɐ mɛmwɑːɹ ɪts pæɾi smɪθz mɛmwɑːɹ.', '<span>It''s</span><span>a</span><span tid="81995" class="highlight highlight-a">memoir</span><span>It''s</span><span tid="81997">Patti</span><span tid="81998">Smith''s</span><span tid="81999" class="highlight highlight-a">memoir.</span>'
FROM episodes e WHERE e.video_id = '099snFJP2ep3QNP';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 154, 589.4, 595.88, 'And she talks about her up-and-coming life as an artist in New York City in the late sixties and seventies.', '她讲述了自己在60至70年代作为艺术家在纽约的崛起经历。', 'ænd ʃiː tɔːks ɐbaʊt hɜːɹ ʌpændkʌmɪŋ laɪf æz ɐn ɑːɹɾɪst ɪn nuː jɔːɹk sɪɾi ɪnðə leɪt sɪkstiz ænd sɛvəntiz.', '<span>And</span><span>she</span><span tid="82002">talks</span><span>about</span><span>her</span><span tid="82005" class="highlight highlight-a">up-and-coming</span><span tid="82006">life</span><span>as</span><span>an</span><span tid="82009" class="highlight highlight-a">artist</span><span>in</span><span tid="82011">New</span><span tid="82012">York</span><span tid="82013">City</span><span>in</span><span>the</span><span tid="82016">late</span><span tid="82017">sixties</span><span>and</span><span tid="82019">seventies.</span>'
FROM episodes e WHERE e.video_id = '099snFJP2ep3QNP';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 155, 595.88, 600.26, 'The kind of names that come up are like Andy Warhol and all the cast characters in that circle.', '书中提到的名字包括Andy Warhol以及圈子里的各类人物。', 'ðə kaɪnd ʌv neɪmz ðæt kʌm ʌp ɑːɹ laɪk ændi wɔːɹhɑːl ænd ɔːl ðə kæst kæɹɪktɚz ɪn ðæt sɜːkəl.', '<span>The</span><span tid="82021">kind</span><span>of</span><span tid="82023">names</span><span>that</span><span tid="82025">come</span><span>up</span><span>are</span><span>like</span><span tid="82029">Andy</span><span tid="82030">Warhol</span><span>and</span><span>all</span><span>the</span><span tid="82034" class="highlight highlight-a">cast</span><span tid="82035" class="highlight highlight-a">characters</span><span>in</span><span>that</span><span tid="82038">circle.</span>'
FROM episodes e WHERE e.video_id = '099snFJP2ep3QNP';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
