FROM episodes e WHERE e.video_id = '099snFJP2ep3QNP';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 158, 604.9, 606.96, 'even though my background is very different.', '即使我的背景完全不同。', 'iːvən ðoʊ maɪ bækɡɹaʊnd ɪz vɛɹi dɪfɹənt.', '<span tid="82056">even</span><span tid="82057">though</span><span>my</span><span tid="82059" class="highlight highlight-a">background</span><span>is</span><span>very</span><span tid="82062">different.</span>'
