INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 72, 338.96, 345.96, 'Only to be distracted again, two seconds later, by pastries, bookstores, and tiny shops.', '结果两秒后，我又被甜点、书店、还有那些小店吸走注意力。', '/oʊnli təbi dɪstɹæktᵻd ɐɡɛn, tuː sɛkəndz leɪɾɚ, baɪ peɪstɹiz, bʊkstɔːɹz, ænd taɪni ʃɑːps./', '<span tid="116139">Only</span><span>to</span><span>be</span><span tid="116142" class="highlight highlight-a">distracted</span><span tid="116143">again,</span><span>two</span><span tid="116145">seconds</span><span tid="116146" class="highlight highlight-a">later,</span><span>by</span><span tid="116148" class="highlight highlight-a">pastries,</span><span tid="116149">bookstores,</span><span>and</span><span tid="116151" class="highlight highlight-a">tiny</span><span tid="116152">shops.</span>'
