INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 79, 373.36, 378.18, 'Doing theatre in a smaller town sounds like fun, or maybe on a big stage.', '在小城演戏听起来挺有趣的，或者去大舞台？', '/duːɪŋ θiəɾɚɹ ɪn ɐ smɔːlɚ taʊn saʊndz laɪk fʌn, ɔːɹ meɪbiː ɔn ɐ bɪɡ steɪdʒ./', '<span>Doing</span><span tid="116187">theatre</span><span>in</span><span>a</span><span tid="116190">smaller</span><span tid="116191">town</span><span tid="116192">sounds</span><span>like</span><span tid="116194">fun,</span><span>or</span><span tid="116196">maybe</span><span>on</span><span>a</span><span tid="116199">big</span><span tid="116200">stage.</span>'
