INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 80, 378.38, 383.48, 'Me, once again, mourning all the lives I want to live but never will.', '而我，又一次在心里悼念那些我想活却永远不会活出的另一种人生。', '/miː, wʌns ɐɡɛn, mɔːɹnɪŋ ɔːl ðə laɪvz aɪ wɔnt tə lɪv bʌt nɛvɚ wɪl./', '<span>Me,</span><span tid="116202" class="highlight highlight-a">once</span><span tid="116203">again,</span><span tid="116204">mourning</span><span>all</span><span>the</span><span tid="116207">lives</span><span>I</span><span>want</span><span>to</span><span tid="116211">live</span><span>but</span><span tid="116213">never</span><span>will.</span>'
