INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 81, 383.48, 386.58, 'On the train back, I thought of something.', '回城的火车上，我突然想到一件事。', '/ɔnðə tɹeɪn bæk, aɪ θɔːt ʌv sʌmθɪŋ./', '<span>On</span><span>the</span><span tid="116217">train</span><span tid="116218" class="highlight highlight-a">back,</span><span>I</span><span>thought</span><span>of</span><span>something.</span>'
