INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 82, 386.86, 391.26, 'You can plan, hope, and do everything right.', '你可以规划、期待、把一切做到最好。', '/juː kæn plæn, hoʊp, ænd duː ɛvɹɪθɪŋ ɹaɪt./', '<span>You</span><span>can</span><span tid="116225">plan,</span><span tid="116226">hope,</span><span>and</span><span>do</span><span tid="116229">everything</span><span tid="116230" class="highlight highlight-a">right.</span>'
