INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 83, 391.32, 397.02, 'but the sun, the sky, the little unplanned moments, they have their own plan.', '但阳光、天空和那些不经意的小瞬间——它们有自己的安排。', '/bʌt ðə sʌn, ðə skaɪ, ðə lɪɾəl ʌnplænd moʊmənts, ðeɪ hæv ðɛɹ oʊn plæn./', '<span>but</span><span>the</span><span tid="116233">sun,</span><span>the</span><span tid="116235">sky,</span><span>the</span><span tid="116237">little</span><span tid="116238">unplanned</span><span tid="116239" class="highlight highlight-a">moments,</span><span>they</span><span>have</span><span>their</span><span tid="116243" class="highlight highlight-a">own</span><span tid="116244">plan.</span>'
