INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 84, 397.26, 401.44, 'Sometimes, if you''re lucky, it''s exactly what you needed.', '有时候，如果你够幸运，那正是你最需要的。', '/sʌmtaɪmz, ɪf jʊɹ lʌki, ɪts ɛɡzæktli wʌt juː niːdᵻd./', '<span tid="116245">Sometimes,</span><span>if</span><span>you''re</span><span tid="116248">lucky,</span><span>it''s</span><span tid="116250">exactly</span><span>what</span><span>you</span><span tid="116253">needed.</span>'
