INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 87, 413.81, 420.68, 'Looking back, not much went according to plan, or at least not according to expectations.', '回过头看，其实没什么事照计划走——至少没照预期走。', '/lʊkɪŋ bæk, nɑːt mʌtʃ wɛnt ɐkɔːɹdɪŋ tə plæn, ɔːɹ æt liːst nɑːt ɐkɔːɹdɪŋ tʊ ɛkspɪkteɪʃənz./', '<span tid="116272" class="highlight highlight-a">Looking</span><span tid="116273" class="highlight highlight-a">back,</span><span>not</span><span tid="116275">much</span><span>went</span><span tid="116277">according</span><span>to</span><span tid="116279">plan,</span><span>or</span><span>at</span><span tid="116282">least</span><span>not</span><span tid="116284">according</span><span>to</span><span tid="116286" class="highlight highlight-a">expectations.</span>'
