INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 88, 420.8, 427.12, 'The frizzy hair, the bland dinners, the crush that I forgot about in two seconds.', '毛躁的头发、寡淡的晚餐、两秒就忘掉的迷恋对象。', '/ðə fɹɪzi hɛɹ, ðə blænd dɪnɚz, ðə kɹʌʃ ðæt aɪ fɚɡɑːt ɐbaʊt ɪn tuː sɛkəndz./', '<span>The</span><span tid="116288">frizzy</span><span tid="116289">hair,</span><span>the</span><span tid="116291" class="highlight highlight-a">bland</span><span tid="116292">dinners,</span><span>the</span><span tid="116294">crush</span><span>that</span><span>I</span><span tid="116297">forgot</span><span>about</span><span>in</span><span>two</span><span tid="116301">seconds.</span>'
