INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 89, 427.36, 429.72, 'none of it was on the itinerary.', '这些事情全都没出现在行程表里。', '/nʌn ʌv ɪt wʌz ɔnðɪ aɪtɪnɚɹɛɹi./', '<span tid="116302">none</span><span>of</span><span>it</span><span>was</span><span>on</span><span>the</span><span tid="116308" class="highlight highlight-a">itinerary.</span>'
