INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 90, 430.22, 433.38, 'Maybe the point isn''t to control everything.', '也许重点根本不是掌控一切。', '/meɪbiː ðə pɔɪnt ɪzənt tə kəntɹoʊl ɛvɹɪθɪŋ./', '<span tid="116309">Maybe</span><span>the</span><span tid="116311">point</span><span tid="116312">isn''t</span><span>to</span><span tid="116314">control</span><span tid="116315">everything.</span>'
