INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 43.26, 50.361, 'that taught me something about, about someone with, with incredible will that even if you don''t know how to do something,', '那教会了我一些关于拥有不可思议意志力的人的事情，即使你不知道如何做某事，', '/ðæt tɑt mi ˈsʌmθɪŋ əˈbaʊt əˈbaʊt ˈsʌmwʌn wɪð wɪð ɪnˈkrɛdəbəl wɪl ðæt ˈivən ɪf ju doʊnt noʊ haʊ tə du ˈsʌmθɪŋ/', '<span>that</span><span>taught</span><span>me</span><span>something</span><span>about</span><span>,</span><span>about</span><span>someone</span><span>with</span><span>,</span><span>with</span><span tid="50009" class="highlight highlight-a">incredible</span><span>will</span><span>that</span><span>even</span><span>if</span><span>you</span><span>don''t</span><span>know</span><span>how</span><span>to</span><span>do</span><span>something</span><span>,</span>'
