INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 215.8, 220.96, 'And so that''s what keeps me showing up every day.', '所以，这正是让我每天继续走下去的原因。', '/ænd soʊ ðæts wʌt kiːps miː ʃoʊɪŋ ʌp ɛvɹi deɪ./', '<span>And</span><span>so</span><span>that''s</span><span>what</span><span tid="110919">keeps</span><span>me</span><span tid="110921">showing</span><span>up</span><span tid="110923">every</span><span>day.</span>'
FROM episodes e WHERE e.video_id = '105iNVJdsJKOlhR';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 220.96, 228.76, 'It''s the friendships and the shared belief that storytelling still matters.', '是这些友谊，也是我们共同相信：讲故事依然重要。', '/ɪts ðə fɹɛndʃɪps ænd ðə ʃɛɹd bᵻliːf ðæt stɔːɹɪtɛlɪŋ stɪl mæɾɚz./', '<span>It''s</span><span>the</span><span tid="110927">friendships</span><span>and</span><span>the</span><span tid="110930" class="highlight highlight-a">shared</span><span tid="110931" class="highlight highlight-a">belief</span><span>that</span><span tid="110933">storytelling</span><span tid="110934">still</span><span tid="110935">matters.</span>'
