INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 37, 228.76, 234.8, 'that bearing our souls as actors and creators still matters.', '作为演员和创作者，袒露灵魂依然重要。', '/ðæt bɛɹɪŋ aʊɚ soʊlz æz æktɚz ænd kɹiːeɪɾɚz stɪl mæɾɚz./', '<span>that</span><span tid="110937" class="highlight highlight-a">bearing</span><span>our</span><span tid="110939" class="highlight highlight-a">souls</span><span>as</span><span tid="110941">actors</span><span>and</span><span tid="110943">creators</span><span tid="110944">still</span><span tid="110945">matters.</span>'
