INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 40, 248.3, 256.6, 'But what I believe back in 2011 still holds true, which is.', '但我在2011年所坚信的东西，直到今天依然成立。', '/bʌt wʌt aɪ bᵻliːv bæk ɪn tuː θaʊzənd ɪlɛvən stɪl hoʊldz tɹuː, wɪtʃ ɪz./', '<span>But</span><span>what</span><span>I</span><span tid="110981">believe</span><span tid="110982" class="highlight highlight-a">back</span><span>in</span><span>2011</span><span tid="110985">still</span><span tid="110986">holds</span><span tid="110987">true,</span><span>which</span><span>is.</span>'
