INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 2.02, 4.12, 'So good to see you guys after a long time.', '好久不见，真的很高兴再次见到大家。', '/soʊ ɡʊd tə siː juː ɡaɪz æftɚɹ ɐ lɔŋ taɪm./', '<span>So</span><span>good</span><span>to</span><span tid="108483">see</span><span>you</span><span tid="108485">guys</span><span tid="108486">after</span><span>a</span><span tid="108488">long</span><span tid="108489">time.</span>'
