INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 92, 387.44, 391.04, 'If you did, press the like button, subscribe to the channel for more such content.', '如果有帮助的话，记得点赞，并订阅频道，获取更多类似内容。', '/ɪf juː dɪd, pɹɛs ðə laɪk bʌʔn̩, səbskɹaɪb tə ðə tʃænəl fɔːɹ mɔːɹ sʌtʃ kɑːntɛnt./', '<span>If</span><span>you</span><span>did,</span><span tid="109703" class="highlight highlight-a">press</span><span>the</span><span>like</span><span tid="109706" class="highlight highlight-a">button,</span><span tid="109707" class="highlight highlight-a">subscribe</span><span>to</span><span>the</span><span tid="109710" class="highlight highlight-a">channel</span><span>for</span><span>more</span><span tid="109713">such</span><span tid="109714" class="highlight highlight-a">content.</span>'
