INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 9.64, 'Hello I am in a hotel and today you will learn all the hotel English you need to know for travelling abroad.', '你好，我现在在一家酒店，今天你将学到出国旅行时需要用到的所有酒店英语。', '/həloʊ aɪɐm ɪn ɐ hoʊtɛl ænd tədeɪ juː wɪl lɜːn ɔːl ðə hoʊtɛl ɪŋɡlɪʃ juː niːd tə noʊ fɔːɹ tɹævəlɪŋ ɐbɹɔːd./', '<span>Hello</span><span>I</span><span>am</span><span>in</span><span>a</span><span tid="106963">hotel</span><span>and</span><span tid="106965">today</span><span>you</span><span>will</span><span tid="106968">learn</span><span>all</span><span>the</span><span tid="106971">hotel</span><span tid="106972">English</span><span>you</span><span tid="106974">need</span><span>to</span><span>know</span><span>for</span><span tid="106978">travelling</span><span tid="106979" class="highlight highlight-a">abroad.</span>'
