INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 82.2, 84.78, 'It''s amazing for your mobility It''s great for your mind.', '对活动能力很棒，对心理状态也非常好。', '/ɪts ɐmeɪzɪŋ fɔːɹ jʊɹ moʊbɪlᵻɾi ɪts ɡɹeɪt fɔːɹ jʊɹ maɪnd./', '<span>It''s</span><span tid="104474">amazing</span><span>for</span><span>your</span><span tid="104477" class="highlight highlight-a">mobility</span><span>It''s</span><span tid="104479">great</span><span>for</span><span>your</span><span tid="104482" class="highlight highlight-a">mind.</span>'
