INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 84.78, 88.82, 'And so I''ll be doing a lot more of that into 2026.', '所以在2026年，我会更多地去练习瑜伽。', '/ænd soʊ aɪl biː duːɪŋ ɐ lɑːt mɔːɹ ʌv ðæt ɪntʊ tuː θaʊzənd twɛnti sɪks./', '<span>And</span><span>so</span><span>I''ll</span><span>be</span><span>doing</span><span>a</span><span tid="104489">lot</span><span>more</span><span>of</span><span>that</span><span tid="104493" class="highlight highlight-a">into</span><span>2026.</span>'
