INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 22, 88.82, 95.26, 'I didn''t fully understand until this year how much food affects everything.', '直到今年我才真正意识到，食物对一切的影响有多大。', '/aɪ dɪdnt fʊli ʌndɚstænd ʌntɪl ðɪs jɪɹ haʊ mʌtʃ fuːd ɐfɛkts ɛvɹɪθɪŋ./', '<span>I</span><span>didn''t</span><span tid="104497">fully</span><span tid="104498">understand</span><span tid="104499" class="highlight highlight-a">until</span><span>this</span><span tid="104501">year</span><span>how</span><span tid="104503">much</span><span tid="104504">food</span><span tid="104505" class="highlight highlight-a">affects</span><span tid="104506">everything.</span>'
