INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 100.28, 105.14, 'When your body is properly fueled, it has the resources it needs to function well.', '当身体得到充足而正确的能量供给时，它才有资源去正常运作。', '/wɛn jʊɹ bɑːdi ɪz pɹɑːpɚli fjuːəld, ɪt hɐz ðə ɹᵻsɔːɹsᵻz ɪt niːdz tə fʌŋkʃən wɛl./', '<span>When</span><span>your</span><span tid="104518">body</span><span>is</span><span tid="104520" class="highlight highlight-a">properly</span><span tid="104521" class="highlight highlight-a">fueled,</span><span>it</span><span>has</span><span>the</span><span tid="104525" class="highlight highlight-a">resources</span><span>it</span><span tid="104527">needs</span><span>to</span><span pid="2632" class="highlight highlight-i">function well.</span>'
