INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 25, 105.14, 108.84, 'Protein supports muscle, metabolism, and hormone health.', '蛋白质支持肌肉、代谢以及激素健康。', '/pɹoʊtiːn səpɔːɹts mʌsəl, mətæbəlɪzəm, ænd hɔːɹmoʊn hɛlθ./', '<span tid="104531" class="highlight highlight-a">Protein</span><span tid="104532">supports</span><span tid="104533" class="highlight highlight-a">muscle,</span><span tid="104534" class="highlight highlight-a">metabolism,</span><span>and</span><span tid="104536" class="highlight highlight-a">hormone</span><span tid="104537">health.</span>'
