INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 108.84, 112.92, 'Fiber feeds your gut, stabilizes blood sugar, and helps reduce inflammation.', '膳食纤维滋养肠道，稳定血糖，并有助于减少炎症。', '/faɪbɚ fiːdz jʊɹ ɡʌt, steɪbɪlaɪzᵻz blʌd ʃʊɡɚ, ænd hɛlps ɹᵻduːs ɪnflæmeɪʃən./', '<span tid="104538" class="highlight highlight-a">Fiber</span><span tid="104539" class="highlight highlight-a">feeds</span><span>your</span><span tid="104541" class="highlight highlight-a">gut,</span><span tid="104542" class="highlight highlight-a">stabilizes</span><span pid="2619" class="highlight highlight-c">blood sugar,</span><span>and</span><span tid="104546">helps</span><span tid="104547" class="highlight highlight-a">reduce</span><span tid="104548" class="highlight highlight-a">inflammation.</span>'
