INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 145.16, 150.58, 'This year, I''ve really leaned into fueling in a way that supports long -term health.', '今年我真的开始更认真地用饮食来支持长期健康。', '/ðɪs jɪɹ, aɪv ɹiəli liːnd ɪntʊ fjuːəlɪŋ ɪn ɐ weɪ ðæt səpɔːɹts lɔŋ tɜːm hɛlθ./', '<span>This</span><span tid="104649">year,</span><span>I''ve</span><span tid="104651">really</span><span pid="2618" class="highlight highlight-c">leaned into</span><span tid="104654" class="highlight highlight-a">fueling</span><span>in</span><span>a</span><span tid="104657" class="highlight highlight-a">way</span><span>that</span><span tid="104659">supports</span><span tid="104660">long</span><span tid="104661" class="highlight highlight-a">-term</span><span tid="104662">health.</span>'
