INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 150.58, 155.36, 'So focusing on making sure I''m hitting my protein goals every day and my fiber goals.', '每天确保蛋白质摄入达标，也保证足够的膳食纤维。', '/soʊ foʊkəsɪŋ ɔn meɪkɪŋ ʃʊɹ aɪm hɪɾɪŋ maɪ pɹoʊtiːn ɡoʊlz ɛvɹi deɪ ænd maɪ faɪbɚ ɡoʊlz./', '<span>So</span><span tid="104664">focusing</span><span>on</span><span tid="104666">making</span><span tid="104667">sure</span><span>I''m</span><span tid="104669" class="highlight highlight-a">hitting</span><span>my</span><span tid="104671" class="highlight highlight-a">protein</span><span tid="104672">goals</span><span tid="104673">every</span><span>day</span><span>and</span><span>my</span><span tid="104677" class="highlight highlight-a">fiber</span><span tid="104678">goals.</span>'
