INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 155.36, 161.06, 'as well as making sure that I''m eating nutrient-rich foods with plenty of antioxidants.', '同时确保摄入富含营养、含有大量抗氧化物的食物。', '/æz wɛl æz meɪkɪŋ ʃʊɹ ðæt aɪm iːɾɪŋ njuːtɹiənt ɹɪtʃ fuːdz wɪð plɛnti ʌv æntɪɑːksɪdənts./', '<span>as</span><span tid="104680">well</span><span>as</span><span tid="104682">making</span><span tid="104683">sure</span><span>that</span><span>I''m</span><span tid="104686">eating</span><span tid="104687">nutrient-rich</span><span tid="104688">foods</span><span>with</span><span tid="104690">plenty</span><span>of</span><span tid="104692" class="highlight highlight-a">antioxidants.</span>'
