INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 39, 176.7, 181.48, 'Moving into 2026, wellness for me is about consistency.', '对我来说，2026年的健康关键词是“持续性”。', '/muːvɪŋ ɪntʊ tuː θaʊzənd twɛnti sɪks, wɛlnəs fɔːɹ miː ɪz ɐbaʊt kənsɪstənsi./', '<span tid="104739">Moving</span><span tid="104740" class="highlight highlight-a">into</span><span>2026,</span><span tid="104742" class="highlight highlight-a">wellness</span><span>for</span><span>me</span><span>is</span><span>about</span><span tid="104747" class="highlight highlight-a">consistency.</span>'
FROM episodes e WHERE e.video_id = '112sWP4yEAH4986';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
