INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 41, 189.52, 191.28, 'Thank you so much for being here.', '非常感谢你一直在这里陪伴。', '/θæŋk juː soʊ mʌtʃ fɔːɹ biːɪŋ hɪɹ./', '<span tid="104770">Thank</span><span>you</span><span>so</span><span tid="104773">much</span><span>for</span><span>being</span><span>here.</span>'
