INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 42, 191.28, 199.28, 'I hope this video gave you some inspiration for wellness habits that you can start to incorporate in 2026 so that you can feel your best.', '希望这支视频能给你一些关于健康习惯的灵感，让你在2026年开始慢慢实践，状态越来越好。', '/aɪ hoʊp ðɪs vɪdɪoʊ ɡeɪv juː sʌm ɪnspɚɹeɪʃən fɔːɹ wɛlnəs hæbɪts ðæt juː kæn stɑːɹt tʊ ɪŋkɔːɹpɚɹeɪt ɪn tuː θaʊzənd twɛnti sɪks soʊ ðæt juː kæn fiːl jʊɹ bɛst./', '<span>I</span><span tid="104778">hope</span><span>this</span><span tid="104780">video</span><span tid="104781">gave</span><span>you</span><span>some</span><span tid="104784" class="highlight highlight-a">inspiration</span><span>for</span><span tid="104786" class="highlight highlight-a">wellness</span><span tid="104787">habits</span><span>that</span><span>you</span><span>can</span><span tid="104791">start</span><span>to</span><span tid="104793" class="highlight highlight-a">incorporate</span><span>in</span><span>2026</span><span>so</span><span>that</span><span>you</span><span>can</span><span tid="104800">feel</span><span>your</span><span>best.</span>'
