  summary = EXCLUDED.summary,
  remark = EXCLUDED.remark,
  stars = EXCLUDED.stars,
  voca_size = EXCLUDED.voca_size,
  subtitle_count = EXCLUDED.subtitle_count,
  clip_length = EXCLUDED.clip_length,
  cover = EXCLUDED.cover,
  video_url = EXCLUDED.video_url,
  audio_url = EXCLUDED.audio_url,
  thumbnail_url = EXCLUDED.thumbnail_url,
  original_video_url = EXCLUDED.original_video_url,
  author_id = EXCLUDED.author_id,
  is_demo = EXCLUDED.is_demo,
  status = EXCLUDED.status,
  published_at = EXCLUDED.published_at;

DELETE FROM user_subtitle_progress WHERE subtitle_id IN (
  SELECT s.id FROM subtitles s JOIN episodes e ON s.episode_id = e.id WHERE e.video_id = '1132DDwdcc6Dw35'
);
DELETE FROM subtitles WHERE episode_id = (SELECT id FROM episodes WHERE video_id = '1132DDwdcc6Dw35');
DELETE FROM episode_tags WHERE episode_id = (SELECT id FROM episodes WHERE video_id = '1132DDwdcc6Dw35');

INSERT INTO episode_tags (episode_id, tag_id)
SELECT e.id, t.id FROM episodes e, tags t
WHERE e.video_id = '1132DDwdcc6Dw35' AND t.name = '日常'
ON CONFLICT DO NOTHING;
