INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 69, 379.72, 387.62, 'A travelator is a flat moving walkway, kind of like an escalator but on one level.', '电动人行道是一种平行移动的人行通道，有点像平面的自动扶梯。', '/ɐ tɹævɪleɪɾɚɹ ɪz ɐ flæt muːvɪŋ wɔːkweɪ, kaɪnd ʌv laɪk ɐn ɛskɐleɪɾɚ bʌt ɔn wʌn lɛvəl./', '<span>A</span><span tid="101745" class="highlight highlight-a">travelator</span><span>is</span><span>a</span><span tid="101748" class="highlight highlight-a">flat</span><span tid="101749">moving</span><span tid="101750">walkway,</span><span tid="101751">kind</span><span>of</span><span>like</span><span>an</span><span tid="101755" class="highlight highlight-a">escalator</span><span>but</span><span>on</span><span>one</span><span tid="101759">level.</span>'
FROM episodes e WHERE e.video_id = '116DnCGpCPdjUJQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
