FROM episodes e WHERE e.video_id = '116DnCGpCPdjUJQ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 71, 394.74, 399.04, 'As I''m walking, I can see airplanes outside of the window.', '走路的时候，我能看到窗外的飞机。', '/æz aɪm wɔːkɪŋ, aɪ kæn siː ɛɹpleɪnz aʊtsaɪd ʌvðə wɪndoʊ./', '<span>As</span><span>I''m</span><span tid="101773">walking,</span><span>I</span><span>can</span><span tid="101776">see</span><span tid="101777">airplanes</span><span tid="101778">outside</span><span>of</span><span>the</span><span tid="101781" class="highlight highlight-a">window.</span>'
