INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 73, 404.0, 409.6, 'The man in front of me has a small carry-on suitcase next to him.', '我前面那位男士旁边有一个小型随身行李箱。', '/ðə mæn ɪn fɹʌnt ʌv miː hɐz ɐ smɔːl kæɹi ɔn suːtkeɪs nɛkst tə hɪm./', '<span>The</span><span tid="101789">man</span><span>in</span><span tid="101791">front</span><span>of</span><span>me</span><span>has</span><span>a</span><span tid="101796">small</span><span pid="2738" class="highlight highlight-c">carry-on suitcase</span><span pid="2718" class="highlight highlight-c">next to</span><span>him.</span>'
