INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 74, 410.44, 415.7, 'For my flight, a carry-on bag must be under seven kilograms to fly.', '我的航班规定随身行李必须低于七公斤。', '/fɔːɹ maɪ flaɪt, ɐ kæɹi ɔn bæɡ mʌst biː ʌndɚ sɛvən kɪləɡɹæmz tə flaɪ./', '<span>For</span><span>my</span><span tid="101804" class="highlight highlight-a">flight,</span><span>a</span><span pid="2739" class="highlight highlight-c">carry-on bag</span><span tid="101808" class="highlight highlight-a">must</span><span>be</span><span tid="101810">under</span><span>seven</span><span tid="101812">kilograms</span><span>to</span><span tid="101814">fly.</span>'
