INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 31, 238.38, 243.6, 'The next morning started at Two Jack Lake, just outside of Banff.', '第二天早晨，我从班夫外的双杰克湖开始。', '/ðə nɛkst mɔːɹnɪŋ stɑːɹɾᵻd æt tuː dʒæk leɪk, dʒʌst aʊtsaɪd ʌv bænf./', '<span>The</span><span tid="100494">next</span><span tid="100495">morning</span><span tid="100496">started</span><span>at</span><span>Two</span><span tid="100499">Jack</span><span tid="100500">Lake,</span><span>just</span><span tid="100502">outside</span><span>of</span><span tid="100504">Banff.</span>'
FROM episodes e WHERE e.video_id = '1174BHAwy5EX5zw';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 32, 243.78, 249.28, 'It was the coldest morning of the trip thus far, only about 8 degrees.', '这是旅行迄今为止最冷的早晨，仅有大约8度（零下13度）。', '/ɪt wʌzðə koʊldɪst mɔːɹnɪŋ ʌvðə tɹɪp ðʌs fɑːɹ, oʊnli ɐbaʊt eɪt dᵻɡɹiːz./', '<span>It</span><span>was</span><span>the</span><span tid="100508" class="highlight highlight-a">coldest</span><span tid="100509">morning</span><span>of</span><span>the</span><span tid="100512">trip</span><span pid="2649" class="highlight highlight-c">thus far,</span><span tid="100515">only</span><span>about</span><span>8</span><span tid="100518">degrees.</span>'
