INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 33, 249.98, 252.84, 'But honestly, I''m here for it.', '但说实话，我很享受这种感觉。', '/bʌt ɑːnɪstli, aɪm hɪɹ fɔːɹ ɪt./', '<span>But</span><span tid="100520" class="highlight highlight-a">honestly,</span><span>I''m</span><span>here</span><span>for</span><span>it.</span>'
