INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 253.1, 259.34, 'After the magic of yesterday, everything from here on out is just a cherry on top for me.', '经历了昨天的魔力之后，从此刻开始的一切，对我来说都是锦上添花。', '/æftɚ ðə mædʒɪk ʌv jɛstɚdeɪ, ɛvɹɪθɪŋ fɹʌm hɪɹ ɔn aʊt ɪz dʒʌst ɐ tʃɛɹi ɔn tɑːp fɔːɹ miː./', '<span tid="100525">After</span><span>the</span><span tid="100527">magic</span><span>of</span><span tid="100529">yesterday,</span><span tid="100530">everything</span><span>from</span><span>here</span><span>on</span><span tid="100534">out</span><span>is</span><span>just</span><span>a</span><span pid="2657" class="highlight highlight-c">cherry on top</span><span>for</span><span>me.</span>'
