INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 36, 267.52, 273.08, 'And out of nowhere, a herd of elk move through the frost-covered grass.', '突然，一群麋鹿从霜覆盖的草地中走过。', '/ænd aʊɾəv noʊwɛɹ, ɐ hɜːd ʌv ɛlk muːv θɹuː ðə fɹɔst kʌvɚd ɡɹæs./', '<span>And</span><span pid="2648" class="highlight highlight-c">out of nowhere,</span><span pid="2658" class="highlight highlight-c">a herd of</span><span tid="100562" class="highlight highlight-a">elk</span><span tid="100563">move</span><span tid="100564">through</span><span>the</span><span tid="100566">frost-covered</span><span tid="100567" class="highlight highlight-a">grass.</span>'
