INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 37, 274.36, 277.66, 'Encounters like this aren''t unusual in these parts.', '在这里遇到这样的场景并不罕见。', '/ɛŋkaʊntɚz laɪk ðɪs ɑːɹnt ʌnjuːʒuːəl ɪn ðiːz pɑːɹts./', '<span tid="100568" class="highlight highlight-a">Encounters</span><span>like</span><span>this</span><span tid="100571">aren''t</span><span tid="100572">unusual</span><span>in</span><span>these</span><span tid="100575">parts.</span>'
