INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 40, 299.2, 302.92, 'Banff has always felt like a theme park for photographers.', '班夫一直感觉像是摄影师的主题公园。', '/bænf hɐz ɔːlweɪz fɛlt laɪk ɐ θiːm pɑːɹk fɔːɹ fətɑːɡɹəfɚz./', '<span tid="100603">Banff</span><span>has</span><span tid="100605">always</span><span pid="2638" class="highlight highlight-i">felt like</span><span>a</span><span pid="2659" class="highlight highlight-c">theme park</span><span>for</span><span tid="100612" class="highlight highlight-a">photographers.</span>'
