INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 0.96, 4.28, 'I mean, you just spent the beginning of the summer down under in Australia.', '你的夏天刚开始时去了澳大利亚，度过了美好的时光。', '/aɪ miːn, juː dʒʌst spɛnt ðə bɪɡɪnɪŋ ʌvðə sʌmɚ daʊn ʌndɚɹ ɪn ɔːstɹeɪliə./', '<span>I</span><span tid="99198">mean,</span><span>you</span><span>just</span><span tid="99201">spent</span><span>the</span><span tid="99203">beginning</span><span>of</span><span>the</span><span tid="99206">summer</span><span tid="99207">down</span><span tid="99208">under</span><span>in</span><span tid="99210">Australia.</span>'
