INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 4.28, 7.82, 'running around doing Mayhem Ball, everyone absolutely loving it.', '忙着巡演，大家都爱死了。', '/ɹʌnɪŋ ɚɹaʊnd duːɪŋ meɪhɛm bɔːl, ɛvɹɪwʌn æbsəluːtli lʌvɪŋ ɪt./', '<span tid="99211">running</span><span tid="99212">around</span><span>doing</span><span tid="99214">Mayhem</span><span tid="99215">Ball,</span><span tid="99216">everyone</span><span tid="99217" class="highlight highlight-a">absolutely</span><span tid="99218">loving</span><span>it.</span>'
