INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 49.02, 55.1, 'doing like unique renditions at the piano every night too has been really fun.', '每天晚上在钢琴上演绎独特的版本也非常有趣。', '/duːɪŋ laɪk juːniːk ɹɛndɪʃənz æt ðə piænoʊ ɛvɹi naɪt tuː hæzbiːn ɹiəli fʌn./', '<span>doing</span><span>like</span><span tid="99334" class="highlight highlight-a">unique</span><span tid="99335" class="highlight highlight-a">renditions</span><span>at</span><span>the</span><span tid="99338">piano</span><span tid="99339">every</span><span tid="99340">night</span><span>too</span><span>has</span><span>been</span><span tid="99344">really</span><span tid="99345">fun.</span>'
FROM episodes e WHERE e.video_id = '1198ijfVESsf0xR';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 55.1, 58.82, 'Bringing out Brooklyn Nights, doing things like that, everyone going crazy.', '演唱《Brooklyn Nights》之类的歌曲，大家都疯狂了。', '/bɹɪŋɪŋ aʊt bɹʊklɪn naɪts, duːɪŋ θɪŋz laɪk ðæt, ɛvɹɪwʌn ɡoʊɪŋ kɹeɪzi./', '<span tid="99346">Bringing</span><span tid="99347">out</span><span tid="99348">Brooklyn</span><span tid="99349">Nights,</span><span>doing</span><span>things</span><span>like</span><span>that,</span><span tid="99354">everyone</span><span>going</span><span tid="99356">crazy.</span>'
