INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 45, 125.08, 128.74, 'you know, because the departure is sort of too great to get back into.', '你知道，因为那种脱离感太强了，很难再找回状态。', '/juː noʊ, bɪkʌz ðə dᵻpɑːɹtʃɚɹ ɪz sɔːɹt ʌv tuː ɡɹeɪt tə ɡɛt bæk ɪntʊ./', '<span>you</span><span>know,</span><span>because</span><span>the</span><span tid="97769">departure</span><span>is</span><span tid="97771">sort</span><span>of</span><span>too</span><span tid="97774">great</span><span>to</span><span>get</span><span tid="97777" class="highlight highlight-a">back</span><span tid="97778" class="highlight highlight-a">into.</span>'
FROM episodes e WHERE e.video_id = '121iAbnIIfxUy7h';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
