INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 50, 182.84, 186.5, 'The whole store environment is designed to reinforce value.', '整个门店环境的设计都是为了强化“物超所值”的理念。', '/ðə hoʊl stɔːɹ ɛnvaɪɹənmənt ɪz dɪzaɪnd tə ɹiːɪnfɔːɹs væljuː./', '<span>The</span><span tid="96682">whole</span><span tid="96683" class="highlight highlight-a">store</span><span tid="96684">environment</span><span>is</span><span tid="96686">designed</span><span>to</span><span tid="96688" class="highlight highlight-a">reinforce</span><span tid="96689">value.</span>'
