FROM episodes e WHERE e.video_id = '123LPSwzyUOkgHZ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 57, 226.06, 230.8, 'I actually grew up coming to this very IKEA here in Burbank, Los Angeles, California.', '其实我从小就经常来加州洛杉矶伯班克的这家宜家。', '/aɪ æktʃuːəli ɡɹuː ʌp kʌmɪŋ tə ðɪs vɛɹi aɪkiːə hɪɹ ɪn bɜːbæŋk, lɑːs ændʒəlɪs, kælɪfɔːɹniə./', '<span>I</span><span tid="96782">actually</span><span tid="96783">grew</span><span>up</span><span tid="96785">coming</span><span>to</span><span>this</span><span>very</span><span tid="96789">IKEA</span><span>here</span><span>in</span><span tid="96792">Burbank,</span><span tid="96793">Los</span><span tid="96794">Angeles,</span><span tid="96795">California.</span>'
