INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 60, 234.94, 238.88, 'Who are these people around me who I once again am desperately trying to avoid to film this video?', '这些在我身边、而我为了拍视频正拼命躲避的人又是谁？', '/huː ɑːɹ ðiːz piːpəl ɚɹaʊnd miː huː aɪ wʌns ɐɡɛn æm dɛspɚɹətli tɹaɪɪŋ tʊ ɐvɔɪd tə fɪlm ðɪs vɪdɪoʊ?/', '<span>Who</span><span>are</span><span>these</span><span tid="96813">people</span><span tid="96814">around</span><span>me</span><span>who</span><span>I</span><span tid="96818" class="highlight highlight-a">once</span><span tid="96819">again</span><span>am</span><span tid="96821" class="highlight highlight-a">desperately</span><span tid="96822">trying</span><span>to</span><span tid="96824" class="highlight highlight-a">avoid</span><span>to</span><span tid="96826" class="highlight highlight-a">film</span><span>this</span><span tid="96828">video?</span>'
