FROM episodes e WHERE e.video_id = '123LPSwzyUOkgHZ';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 62, 247.16, 253.9, 'You also get budget-conscious homeowners of all ages, young families, city dwellers picking up small space solutions.', '你还能看到各个年龄段精打细算的房主、年轻家庭，以及挑选小空间解决方案的城市居民。', '/juː ɔːlsoʊ ɡɛt bʌdʒɪt kɑːnʃəs hoʊmoʊnɚz ʌv ɔːl eɪdʒᵻz, jʌŋ fæmɪliz, sɪɾi dwɛlɚz pɪkɪŋ ʌp smɔːl speɪs səluːʃənz./', '<span>You</span><span>also</span><span>get</span><span tid="96861" class="highlight highlight-a">budget-conscious</span><span tid="96862">homeowners</span><span>of</span><span>all</span><span tid="96865" class="highlight highlight-a">ages,</span><span tid="96866">young</span><span tid="96867">families,</span><span pid="2936" class="highlight highlight-c">city dwellers</span><span tid="96870">picking</span><span>up</span><span tid="96872">small</span><span tid="96873">space</span><span tid="96874" class="highlight highlight-a">solutions.</span>'
