INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 21.06, 26.46, 'In fact, happiness wouldn''t exist without sadness.', '事实上，如果没有痛苦，快乐也就失去了意义。', '/ɪn fækt, hæpɪnəs wʊdənt ɛɡzɪst wɪðaʊt sædnəs./', '<span>In</span><span tid="95655">fact,</span><span tid="95656">happiness</span><span>wouldn''t</span><span tid="95658">exist</span><span tid="95659">without</span><span tid="95660">sadness.</span>'
