INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 46.68, 50.44, 'So happiness cannot exist without sadness.', '所以，没有痛苦，快乐就无法存在。', '/soʊ hæpɪnəs kænɑːt ɛɡzɪst wɪðaʊt sædnəs./', '<span>So</span><span tid="95703">happiness</span><span>cannot</span><span tid="95705">exist</span><span tid="95706">without</span><span tid="95707">sadness.</span>'
