INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 50.44, 54.04, 'Thus, it''s impossible to be happy all the time.', '因此，人是不可能时刻都感到快乐的。', '/ðʌs, ɪts ɪmpɑːsᵻbəl təbi hæpi ɔːl ðə taɪm./', '<span tid="95708">Thus,</span><span>it''s</span><span tid="95710">impossible</span><span>to</span><span>be</span><span tid="95713">happy</span><span pid="3362" class="highlight highlight-c">all the time.</span>'
