INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 57, 227.4, 229.56, 'There would be nothing pushing us to grow.', '没有任何动力去推着我们进步。', '/ðɛɹ wʊd biː nʌθɪŋ pʊʃɪŋ ʌs tə ɡɹoʊ./', '<span>There</span><span>would</span><span>be</span><span tid="96163">nothing</span><span tid="96164" class="highlight highlight-a">pushing</span><span>us</span><span>to</span><span tid="96167">grow.</span>'
