INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 58, 229.56, 234.2, 'and growth is so important and it has the potential to create more positive emotion.', '而成长是如此重要，它拥有创造更多正面情绪的无限潜力。', '/ænd ɡɹoʊθ ɪz soʊ ɪmpɔːɹtənt ænd ɪt hɐz ðə pətɛnʃəl tə kɹiːeɪt mɔːɹ pɑːzᵻtɪv ɪmoʊʃən./', '<span>and</span><span tid="96169">growth</span><span>is</span><span>so</span><span tid="96172">important</span><span>and</span><span>it</span><span>has</span><span>the</span><span tid="96177" class="highlight highlight-a">potential</span><span>to</span><span tid="96179">create</span><span>more</span><span tid="96181" class="highlight highlight-a">positive</span><span tid="96182" class="highlight highlight-a">emotion.</span>'
FROM episodes e WHERE e.video_id = '124dH1lVslZnfOK';

