INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 32, 211.32, 217.46, 'I''m feeling so sad to leave my hometown and my family and the beautiful beautiful winter weather.', '要离开家乡、家人和这绝美的冬日美景，我又感到非常不舍。', '/aɪm fiːlɪŋ soʊ sæd tə liːv maɪ hoʊmtaʊn ænd maɪ fæmɪli ænd ðə bjuːɾifəl bjuːɾifəl wɪntɚ wɛðɚ./', '<span>I''m</span><span tid="94559">feeling</span><span>so</span><span tid="94561">sad</span><span>to</span><span tid="94563">leave</span><span>my</span><span tid="94565" class="highlight highlight-a">hometown</span><span>and</span><span>my</span><span tid="94568">family</span><span>and</span><span>the</span><span tid="94571">beautiful</span><span tid="94572">beautiful</span><span tid="94573">winter</span><span tid="94574">weather.</span>'
