INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 0.56, 6.72, 'One year ago, I made a video trying to capture what college really feels like.', '一年前，我拍了一个视频，试图记录真实的大学生活。', '/wʌn jɪɹ ɐɡoʊ, aɪ meɪd ɐ vɪdɪoʊ tɹaɪɪŋ tə kæptʃɚ wʌt kɑːlɪdʒ ɹiəli fiːlz laɪk./', '<span>One</span><span tid="3005">year</span><span tid="3006">ago,</span><span>I</span><span tid="3008">made</span><span>a</span><span tid="3010">video</span><span tid="3011">trying</span><span>to</span><span tid="3013" class="highlight highlight-a">capture</span><span>what</span><span tid="3015">college</span><span tid="3016">really</span><span pid="1812" class="highlight highlight-i">feels like.</span>'
