INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 21.1, 30.12, 'I''ve tried my best to stay consistent on all my good habits, but a couple of them I''ve lost.', '我一直在努力保持良好的生活习惯，但有些还是没能坚持下来。', '/aɪv tɹaɪd maɪ bɛst tə steɪ kənsɪstənt ɔn ɔːl maɪ ɡʊd hæbɪts, bʌt ɐ kʌpəl ʌv ðɛm aɪv lɔst./', '<span>I''ve</span><span pid="1820" class="highlight highlight-i">tried my best to</span><span tid="3069">stay</span><span tid="3070" class="highlight highlight-a">consistent</span><span>on</span><span>all</span><span>my</span><span>good</span><span tid="3075">habits,</span><span>but</span><span pid="1821" class="highlight highlight-c">a couple of</span><span>them</span><span>I''ve</span><span tid="3082">lost.</span>'
