INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 37.2, 39.76, 'So I was wondering if y''all think I can grow a beard or something.', '所以我在想，你们觉得我能留胡子吗？', '/soʊ aɪ wʌz wʌndɚɹɪŋ ɪf waɪ ɔːl θɪŋk aɪ kæn ɡɹoʊ ɐ bɪɹd ɔːɹ sʌmθɪŋ./', '<span>So</span><span>I</span><span>was</span><span tid="3111" class="highlight highlight-a">wondering</span><span>if</span><span tid="3113">y''all</span><span>think</span><span>I</span><span>can</span><span tid="3117">grow</span><span>a</span><span tid="3119" class="highlight highlight-a">beard</span><span pid="1824" class="highlight highlight-f">or something.</span>'
