FROM episodes e WHERE e.video_id = '126gAeYfXmtQH3K';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 44.6, 51.12, 'There is nothing worse than making it through your entire day then realizing you just had a flat spot on the side of your head from the way you slept.', '没什么比过完一整天，才发现后脑勺因为睡觉压平了一块更糟糕的了。', '/ðɛɹ ɪz nʌθɪŋ wɜːs ðɐn meɪkɪŋ ɪt θɹuː jʊɹ ɛntaɪɚ deɪ ðɐn ɹiːəlaɪzɪŋ juː dʒʌst hæd ɐ flæt spɑːt ɔnðə saɪd ʌv jʊɹ hɛd fɹʌmðə weɪ juː slɛpt./', '<span>There</span><span>is</span><span tid="3137">nothing</span><span tid="3138">worse</span><span tid="3139">than</span><span tid="3140">making</span><span>it</span><span tid="3142">through</span><span>your</span><span tid="3144" class="highlight highlight-a">entire</span><span>day</span><span>then</span><span tid="3147" class="highlight highlight-a">realizing</span><span>you</span><span>just</span><span>had</span><span>a</span><span tid="3152" class="highlight highlight-a">flat</span><span tid="3153" class="highlight highlight-a">spot</span><span>on</span><span>the</span><span tid="3156">side</span><span>of</span><span>your</span><span tid="3159">head</span><span>from</span><span>the</span><span tid="3162" class="highlight highlight-a">way</span><span>you</span><span tid="3164">slept.</span>'
FROM episodes e WHERE e.video_id = '126gAeYfXmtQH3K';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 14, 51.12, 55.56, 'Lately, I''ve been feeling way more tired than usual.', '最近，我感觉比平时累得多。', '/leɪtli, aɪv bɪn fiːlɪŋ weɪ mɔːɹ taɪɚd ðɐn juːʒuːəl./', '<span tid="3165" class="highlight highlight-a">Lately,</span><span>I''ve</span><span>been</span><span tid="3168">feeling</span><span pid="1827" class="highlight highlight-c">way more</span><span tid="3171">tired</span><span pid="1829" class="highlight highlight-c">than usual.</span>'
