INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 15, 55.56, 59.6, 'It could be a lot of things, but I think I''m just going to blame the weather on this one.', '原因可能有很多，但我打算把锅甩给天气。', '/ɪt kʊd biː ɐ lɑːt ʌv θɪŋz, bʌt aɪ θɪŋk aɪm dʒʌst ɡoʊɪŋ tə bleɪm ðə wɛðɚɹ ɔn ðɪswʌn./', '<span>It</span><span>could</span><span>be</span><span>a</span><span tid="3178">lot</span><span>of</span><span>things,</span><span>but</span><span>I</span><span>think</span><span>I''m</span><span>just</span><span>going</span><span>to</span><span tid="3188" class="highlight highlight-a">blame</span><span>the</span><span tid="3190">weather</span><span>on</span><span>this</span><span>one.</span>'
