INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 16, 59.6, 63.12, 'One thing I''ve definitely been lacking on recently is eating breakfast.', '最近有一件事我确实没做好，那就是吃早饭。', '/wʌn θɪŋ aɪv dɛfɪnətli bɪn lækɪŋ ɔn ɹiːsəntli ɪz iːɾɪŋ bɹɛkfəst./', '<span>One</span><span>thing</span><span>I''ve</span><span tid="3197" class="highlight highlight-a">definitely</span><span>been</span><span tid="3199" class="highlight highlight-a">lacking</span><span>on</span><span tid="3201">recently</span><span>is</span><span tid="3203">eating</span><span tid="3204">breakfast.</span>'
