INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 18, 67.74, 72.02, 'So I decided that as long as I eat something, it''s better than nothing.', '所以我决定，只要吃点东西，总比什么都不吃强。', '/soʊ aɪ dᵻsaɪdᵻd ðæt æz lɔŋ æz aɪ iːt sʌmθɪŋ, ɪts bɛɾɚ ðɐn nʌθɪŋ./', '<span>So</span><span>I</span><span tid="3223">decided</span><span>that</span><span pid="1810" class="highlight highlight-i">as long as</span><span>I</span><span tid="3229">eat</span><span>something,</span><span>it''s</span><span tid="3232">better</span><span tid="3233">than</span><span tid="3234">nothing.</span>'
