INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 19, 72.02, 74.42, 'That''s why most mornings, it''s just cereal.', '这就是为什么大多数早晨，我只吃麦片。', '/ðæts waɪ moʊst mɔːɹnɪŋz, ɪts dʒʌst siəɹɪəl./', '<span>That''s</span><span>why</span><span tid="3237">most</span><span tid="3238">mornings,</span><span>it''s</span><span>just</span><span tid="3241" class="highlight highlight-a">cereal.</span>'
