INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 25, 99.16, 101.34, 'and I''m so much happier again.', '我又满血复活了。', '/ænd aɪm soʊ mʌtʃ hæpɪɚɹ ɐɡɛn./', '<span>and</span><span>I''m</span><span>so</span><span tid="3328">much</span><span tid="3329">happier</span><span tid="3330">again.</span>'
