INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 26, 101.34, 107.56, 'My first class of the day is Physics 2.', '我今天的第一节课是物理 2。', '/maɪ fɜːst klæs ʌvðə deɪ ɪz fɪzɪks tuː./', '<span>My</span><span tid="3332">first</span><span tid="3333">class</span><span>of</span><span>the</span><span>day</span><span>is</span><span tid="3338" class="highlight highlight-a">Physics</span><span>2.</span>'
