INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 27, 107.56, 110.14, 'This is the one class I actually sit in the back.', '这是唯一一门我坐在后排的课。', '/ðɪs ɪz ðə wʌn klæs aɪ æktʃuːəli sɪt ɪnðə bæk./', '<span>This</span><span>is</span><span>the</span><span>one</span><span tid="3344">class</span><span>I</span><span tid="3346">actually</span><span tid="3347">sit</span><span>in</span><span>the</span><span tid="3350" class="highlight highlight-a">back.</span>'
