INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 29, 113.62, 115.42, 'I''m not sure how many people are in here.', '我不确定教室里有多少人，', '/aɪm nɑːt ʃʊɹ haʊ mɛni piːpəl ɑːɹ ɪn hɪɹ./', '<span>I''m</span><span>not</span><span tid="3366">sure</span><span>how</span><span>many</span><span tid="3369">people</span><span>are</span><span>in</span><span>here.</span>'
