INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 49, 201.96, 208.18, 'So yeah, I guess being late sometimes is just a part of what college really looks like.', '所以，好吧，我想偶尔迟到也是真实大学生活的一部分。', '/soʊ jɛh, aɪ ɡɛs biːɪŋ leɪt sʌmtaɪmz ɪz dʒʌst ɐ pɑːɹt ʌv wʌt kɑːlɪdʒ ɹiəli lʊks laɪk./', '<span>So</span><span>yeah,</span><span>I</span><span tid="3635">guess</span><span>being</span><span tid="3637">late</span><span tid="3638">sometimes</span><span>is</span><span>just</span><span>a</span><span tid="3642">part</span><span>of</span><span>what</span><span tid="3645">college</span><span tid="3646">really</span><span tid="3647" class="highlight highlight-a">looks</span><span>like.</span>'
