DELETE FROM user_subtitle_progress WHERE subtitle_id IN (
  SELECT s.id FROM subtitles s JOIN episodes e ON s.episode_id = e.id WHERE e.video_id = '128ggRxcztvDmEa'
);
DELETE FROM subtitles WHERE episode_id = (SELECT id FROM episodes WHERE video_id = '128ggRxcztvDmEa');
DELETE FROM episode_tags WHERE episode_id = (SELECT id FROM episodes WHERE video_id = '128ggRxcztvDmEa');

INSERT INTO episode_tags (episode_id, tag_id)
SELECT e.id, t.id FROM episodes e, tags t
WHERE e.video_id = '128ggRxcztvDmEa' AND t.name = '社交'
ON CONFLICT DO NOTHING;
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 4.08, 'Ever walk away from a conversation thinking, Why did I say that?', '你是否曾在这场谈话后离开时心想：我为什么要说那样的话？', '/ɛvɚ wɔːk ɐweɪ fɹʌm ɐ kɑːnvɚseɪʃən θɪŋkɪŋ, waɪ dɪd aɪ seɪ ðæt?/', '<span tid="1661" class="highlight highlight-a">Ever</span><span tid="1662">walk</span><span tid="1663">away</span><span>from</span><span>a</span><span tid="1666">conversation</span><span tid="1667">thinking,</span><span>Why</span><span>did</span><span>I</span><span tid="1671">say</span><span>that?</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 4.08, 5.1, 'Yeah, me too.', '没错，我也是。', '/jɛh, miː tuː./', '<span>Yeah,</span><span>me</span><span>too.</span>'
