INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 7, 14.8, 21.36, 'Once I figured out a few key shifts, that awkward second-guessing feeling basically disappeared.', '一旦我掌握了几个关键的思维转变，那种尴尬的自我怀疑感基本上就消失了。', '/wʌns aɪ fɪɡɚd aʊt ɐ fjuː kiː ʃɪfts, ðæt ɔːkwɚd sɛkənd ɡɛsɪŋ fiːlɪŋ beɪsɪkli dɪsɐpɪɹd./', '<span tid="1706" class="highlight highlight-a">Once</span><span>I</span><span pid="1592" class="highlight highlight-d">figured out</span><span>a</span><span tid="1711">few</span><span tid="1712" class="highlight highlight-a">key</span><span tid="1713" class="highlight highlight-a">shifts,</span><span>that</span><span tid="1715" class="highlight highlight-a">awkward</span><span tid="1716">second-guessing</span><span tid="1717">feeling</span><span tid="1718" class="highlight highlight-a">basically</span><span tid="1719" class="highlight highlight-a">disappeared.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 8, 21.36, 24.1, 'Not because I suddenly became extroverted.', '不是因为我突然变得外向了。', '/nɑːt bɪkʌz aɪ sʌdənli bɪkeɪm ɛkstɹəvɜːɾᵻd./', '<span>Not</span><span>because</span><span>I</span><span tid="1723">suddenly</span><span tid="1724">became</span><span tid="1725">extroverted.</span>'
