INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 9, 24.1, 27.3, 'Not because I memorized better lines.', '也不是因为我背下了更好的台词。', '/nɑːt bɪkʌz aɪ mɛmɚɹaɪzd bɛɾɚ laɪnz./', '<span>Not</span><span>because</span><span>I</span><span tid="1729" class="highlight highlight-a">memorized</span><span tid="1730">better</span><span tid="1731">lines.</span>'
