INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 10, 27.3, 32.76, 'Because I learned how confident people actually think during conversations.', '而是因为我学会了自信的人在交谈中究竟是如何思考的。', '/bɪkʌz aɪ lɜːnd haʊ kɑːnfɪdənt piːpəl æktʃuːəli θɪŋk dʊɹɹɪŋ kɑːnvɚseɪʃənz./', '<span>Because</span><span>I</span><span tid="1734">learned</span><span>how</span><span tid="1736">confident</span><span tid="1737">people</span><span tid="1738">actually</span><span>think</span><span tid="1740">during</span><span tid="1741">conversations.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 11, 32.76, 36.36, 'In this video, I''ve got six super practical tips to share with you.', '在这段视频中，我有六个超级实用的技巧要与你分享。', '/ɪn ðɪs vɪdɪoʊ, aɪv ɡɑːt sɪks suːpɚ pɹæktɪkəl tɪps tə ʃɛɹ wɪð juː./', '<span>In</span><span>this</span><span tid="1744">video,</span><span>I''ve</span><span>got</span><span>six</span><span tid="1748" class="highlight highlight-a">super</span><span tid="1749" class="highlight highlight-a">practical</span><span tid="1750" class="highlight highlight-a">tips</span><span>to</span><span tid="1752" class="highlight highlight-a">share</span><span>with</span><span>you.</span>'
