INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 12, 36.36, 37.94, 'So let''s get straight into it.', '那我们直接进入正题。', '/soʊ lɛts ɡɛt stɹeɪt ɪntʊ ɪt./', '<span>So</span><span pid="1603" class="highlight highlight-i">let''s get straight into it.</span>'
