INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 13, 37.94, 44.68, 'And the first one has nothing to do with personality and everything to do with where your attention is.', '第一个技巧与性格无关，而完全取决于你的注意力放在哪里。', '/ænd ðə fɜːst wʌn hɐz nʌθɪŋ tə duː wɪð pɜːsənælᵻɾi ænd ɛvɹɪθɪŋ tə duː wɪð wɛɹ jʊɹ ɐtɛnʃən ɪz./', '<span>And</span><span>the</span><span tid="1763">first</span><span>one</span><span pid="1604" class="highlight highlight-f">has nothing to do with</span><span tid="1770" class="highlight highlight-a">personality</span><span>and</span><span tid="1772">everything</span><span>to</span><span>do</span><span>with</span><span>where</span><span>your</span><span tid="1778" class="highlight highlight-a">attention</span><span>is.</span>'
