INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 20, 66.68, 70.24, 'And the moment that happens, the conversation tightens.', '一旦这种念头出现，谈话气氛就开始变得紧绷。', '/ænd ðə moʊmənt ðæt hæpənz, ðə kɑːnvɚseɪʃən taɪʔn̩z./', '<span>And</span><span>the</span><span tid="1835" class="highlight highlight-a">moment</span><span>that</span><span tid="1837">happens,</span><span>the</span><span tid="1839">conversation</span><span tid="1840" class="highlight highlight-a">tightens.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 21, 70.24, 75.44, 'Because you hesitate, you rush, you start editing yourself in real time.', '因为你会犹豫、会急躁，开始实时地对自己进行“审查”。', '/bɪkʌz juː hɛzᵻteɪt, juː ɹʌʃ, juː stɑːɹt ɛdɪɾɪŋ jɔːɹsɛlf ɪn ɹiːəl taɪm./', '<span>Because</span><span>you</span><span tid="1843" class="highlight highlight-a">hesitate,</span><span>you</span><span tid="1845" class="highlight highlight-a">rush,</span><span>you</span><span tid="1847">start</span><span tid="1848">editing</span><span tid="1849">yourself</span><span pid="1597" class="highlight highlight-c">in real time.</span>'
