INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 23, 76.52, 79.22, 'This isn''t actually about confidence at all.', '这其实跟自信完全没关系。', '/ðɪs ɪzənt æktʃuːəli ɐbaʊt kɑːnfɪdəns æɾ ɔːl./', '<span>This</span><span tid="1858">isn''t</span><span tid="1859">actually</span><span>about</span><span tid="1861">confidence</span><span>at</span><span>all.</span>'
