INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 24, 79.22, 82.0, 'It''s about where your attention is pointed.', '这关系到你注意力的指向。', '/ɪts ɐbaʊt wɛɹ jʊɹ ɐtɛnʃən ɪz pɔɪntᵻd./', '<span>It''s</span><span>about</span><span>where</span><span>your</span><span tid="1868" class="highlight highlight-a">attention</span><span>is</span><span tid="1870">pointed.</span>'
