INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 29, 102.98, 108.84, 'the conversation starts to feel really effortful and stilted and a little off.', '谈话就会开始变得费力、生硬，且有些不对劲。', '/ðə kɑːnvɚseɪʃən stɑːɹts tə fiːl ɹiəli ɛfɚtfəl ænd stɪltᵻd ænd ɐ lɪɾəl ɔf./', '<span>the</span><span tid="1919">conversation</span><span tid="1920">starts</span><span>to</span><span tid="1922">feel</span><span tid="1923">really</span><span tid="1924">effortful</span><span>and</span><span tid="1926">stilted</span><span>and</span><span>a</span><span tid="1929">little</span><span tid="1930">off.</span>'
