INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 30, 108.84, 113.24, 'The people who come across as confident in conversation, they aren''t more polished.', '那些在谈话中显得自信的人，并不是因为他们更圆滑。', '/ðə piːpəl huː kʌm əkɹɑːs æz kɑːnfɪdənt ɪn kɑːnvɚseɪʃən, ðeɪ ɑːɹnt mɔːɹ pɑːlɪʃt./', '<span>The</span><span tid="1932">people</span><span>who</span><span pid="1594" class="highlight highlight-d">come across</span><span>as</span><span tid="1937">confident</span><span>in</span><span tid="1939">conversation,</span><span>they</span><span tid="1941">aren''t</span><span>more</span><span tid="1943" class="highlight highlight-a">polished.</span>'
