INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 33, 121.02, 124.4, 'And once you understand that, everything shifts.', '一旦你理解了这一点，一切都会随之改变。', '/ænd wʌns juː ʌndɚstænd ðæt, ɛvɹɪθɪŋ ʃɪfts./', '<span>And</span><span tid="1959" class="highlight highlight-a">once</span><span>you</span><span tid="1961">understand</span><span>that,</span><span tid="1963">everything</span><span tid="1964" class="highlight highlight-a">shifts.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 34, 124.4, 127.94, 'That''s why the first and most important move is this.', '这就是为什么第一步也是最重要的一步是：', '/ðæts waɪ ðə fɜːst ænd moʊst ɪmpɔːɹtənt muːv ɪz ðɪs./', '<span>That''s</span><span>why</span><span>the</span><span tid="1968">first</span><span>and</span><span tid="1970">most</span><span tid="1971">important</span><span tid="1972">move</span><span>is</span><span>this.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 35, 127.94, 130.52, 'Stop trying to sound interesting.', '停止尝试让自己听起来很有趣。', '/stɑːp tɹaɪɪŋ tə saʊnd ɪntɹɛstɪŋ./', '<span tid="1975">Stop</span><span tid="1976">trying</span><span>to</span><span tid="1978">sound</span><span tid="1979">interesting.</span>'
