INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 37, 132.9, 136.5, 'Because the moment you stop performing, you stop overthinking.', '因为当你停止表演的那一刻，你就停止了过度思考。', '/bɪkʌz ðə moʊmənt juː stɑːp pɚfɔːɹmɪŋ, juː stɑːp oʊvɚθɪŋkɪŋ./', '<span>Because</span><span>the</span><span tid="1985" class="highlight highlight-a">moment</span><span>you</span><span tid="1987">stop</span><span tid="1988" class="highlight highlight-a">performing,</span><span>you</span><span tid="1990">stop</span><span tid="1991">overthinking.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 38, 136.5, 140.64, 'And when you stop overthinking, conversation starts to flow.', '而当你停止过度思考，谈话就开始流动起来。', '/ænd wɛn juː stɑːp oʊvɚθɪŋkɪŋ, kɑːnvɚseɪʃən stɑːɹts tə floʊ./', '<span>And</span><span>when</span><span>you</span><span tid="1995">stop</span><span tid="1996">overthinking,</span><span tid="1997">conversation</span><span tid="1998">starts</span><span>to</span><span tid="2000" class="highlight highlight-a">flow.</span>'
