INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 39, 140.64, 146.26, 'Now, once you''ve shifted your attention outward, there is a second mistake that trips people up.', '现在，一旦你把注意力转向外部，还有第二个容易让人栽跟头的错误。', '/naʊ, wʌns juːv ʃɪftᵻd jʊɹ ɐtɛnʃən aʊtwɚd, ðɛɹ ɪz ɐ sɛkənd mɪsteɪk ðæt tɹɪps piːpəl ʌp./', '<span tid="2001">Now,</span><span tid="2002" class="highlight highlight-a">once</span><span>you''ve</span><span tid="2004" class="highlight highlight-a">shifted</span><span>your</span><span tid="2006" class="highlight highlight-a">attention</span><span tid="2007" class="highlight highlight-a">outward,</span><span>there</span><span>is</span><span>a</span><span tid="2011">second</span><span tid="2012" class="highlight highlight-a">mistake</span><span>that</span><span pid="1598" class="highlight highlight-d">trips people up.</span>'
FROM episodes e WHERE e.video_id = '128ggRxcztvDmEa';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
